{
  "name": "PDF MITRA - Pro PDF Suite",
  "description": "A high-performance, privacy-first PDF management suite. Merge, split, compress, and convert PDFs entirely in your browser. Features a built-in AI document assistant.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ToolCategory {
  CONVERT = 'convert',
  ORGANIZE = 'organize',
  SECURITY = 'security',
  OPTIMIZE = 'optimize',
  EDIT = 'edit'
}

export interface PDFTool {
  id: string;
  name: string;
  description: string;
  category: ToolCategory;
  icon: string;
  path: string;
  color: string;
  isNew?: boolean;
  isPopular?: boolean;
}

export interface ProcessingState {
  status: 'idle' | 'loading' | 'processing' | 'success' | 'error';
  progress: number;
  message?: string;
  resultUrl?: string;
  resultFileName?: string;
}

import React, { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { TOOLS } from '../constants';
import { ToolCategory } from '../types';

const Home: React.FC = () => {
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<ToolCategory | 'all'>('all');

  const categories = [
    { label: 'All Tools', value: 'all' },
    { label: 'Convert', value: ToolCategory.CONVERT },
    { label: 'Organize', value: ToolCategory.ORGANIZE },
    { label: 'Security', value: ToolCategory.SECURITY },
    { label: 'Optimize', value: ToolCategory.OPTIMIZE },
  ];

  const filteredTools = useMemo(() => {
    return TOOLS.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'all' || tool.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [search, activeCategory]);

  return (
    <div className="pb-20">
      {/* Hero Section */}
      <section className="bg-white border-b border-slate-200 py-16 px-4">
        <div className="max-w-4xl mx-auto text-center">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-teal-50 border border-teal-100 text-teal-700 text-xs font-bold uppercase tracking-widest mb-6">
            <i className="fas fa-shield-alt"></i> Private & Local
          </div>
          <h1 className="text-4xl md:text-6xl font-extrabold text-slate-900 mb-6 tracking-tight">
            Your Premium <span className="text-teal-600">PDF Mitra</span><br />
            Now Powered by <span className="text-orange-500 italic">AI</span>
          </h1>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto mb-10">
            Professional document tools that run entirely in your browser. 
            No uploads, no cloud, just pure security.
          </p>

          <div className="relative max-w-2xl mx-auto">
            <i className="fas fa-search absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 text-lg"></i>
            <input 
              type="text"
              placeholder="Search tools (e.g. Merge, AI, Compress)..."
              className="w-full pl-16 pr-6 py-5 rounded-2xl bg-white border-2 border-slate-100 focus:border-teal-500 focus:ring-4 focus:ring-teal-500/10 transition-all text-lg font-medium shadow-xl shadow-slate-200/50"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>
      </section>

      {/* Tools Section */}
      <div className="max-w-7xl mx-auto px-4 mt-12">
        <div className="flex gap-2 overflow-x-auto pb-4 mb-8 no-scrollbar">
          {categories.map((cat) => (
            <button
              key={cat.value}
              onClick={() => setActiveCategory(cat.value as any)}
              className={`px-6 py-2.5 rounded-full text-sm font-bold whitespace-nowrap transition-all ${
                activeCategory === cat.value 
                ? 'bg-slate-900 text-white shadow-lg shadow-slate-900/20' 
                : 'bg-white text-slate-600 border border-slate-200 hover:border-teal-500 hover:text-teal-600'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredTools.map((tool) => (
            <Link 
              to={tool.path} 
              key={tool.id}
              className="group bg-white p-8 rounded-3xl border border-slate-200 hover:border-teal-500 transition-all hover:-translate-y-2 hover:shadow-2xl hover:shadow-teal-500/10 relative overflow-hidden"
            >
              <div 
                className="w-16 h-16 rounded-2xl flex items-center justify-center text-3xl mb-6 transition-transform group-hover:scale-110 group-hover:rotate-6"
                style={{ backgroundColor: `${tool.color}15`, color: tool.color }}
              >
                <i className={`fas ${tool.icon}`}></i>
              </div>
              <h3 className="text-xl font-bold text-slate-900 mb-2">{tool.name}</h3>
              <p className="text-slate-500 text-sm leading-relaxed">{tool.description}</p>

              {tool.isNew && (
                <span className="absolute top-6 right-6 px-3 py-1 bg-teal-500 text-white text-[10px] font-black uppercase tracking-wider rounded-full">New</span>
              )}
              {tool.isPopular && (
                <span className="absolute top-6 right-6 px-3 py-1 bg-orange-500 text-white text-[10px] font-black uppercase tracking-wider rounded-full">Popular</span>
              )}
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;

import React, { useRef, useState } from 'react';

interface DropzoneProps {
  onFilesSelected: (files: File[]) => void;
  accept?: string;
  multiple?: boolean;
  title?: string;
  description?: string;
  icon?: string;
}

const Dropzone: React.FC<DropzoneProps> = ({ 
  onFilesSelected, 
  accept = "application/pdf", 
  multiple = false,
  title = "Select or Drag & Drop PDF",
  description = "Processing happens 100% locally on your machine.",
  icon = "fa-cloud-upload-alt"
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      onFilesSelected(Array.from(e.target.files));
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files) {
      const files = Array.from(e.dataTransfer.files);
      // Basic filter for accepted types
      const filtered = accept.includes('*') 
        ? files 
        : files.filter(f => accept.split(',').some(a => f.type.includes(a.trim().replace('*', ''))));
      onFilesSelected(filtered);
    }
  };

  return (
    <div 
      className={`relative group cursor-pointer transition-all ${isDragging ? 'scale-[0.99]' : ''}`}
      onClick={() => inputRef.current?.click()}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={handleDrop}
    >
      <input 
        type="file" 
        ref={inputRef} 
        onChange={handleFileChange} 
        accept={accept} 
        multiple={multiple} 
        className="hidden" 
      />
      <div className={`
        border-4 border-dashed rounded-[2.5rem] p-16 text-center transition-all duration-300
        ${isDragging 
          ? 'border-teal-500 bg-teal-50/50 shadow-inner' 
          : 'border-slate-200 bg-white hover:border-teal-400 group-hover:bg-slate-50/50 group-hover:shadow-xl group-hover:shadow-slate-200/50'}
      `}>
        <div className={`
          w-24 h-24 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-8 transition-all
          ${isDragging ? 'bg-teal-500 text-white scale-110' : 'bg-slate-100 text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 group-hover:-translate-y-2'}
        `}>
          <i className={`fas ${icon}`}></i>
        </div>
        <h3 className="text-2xl font-extrabold text-slate-900 mb-2">{title}</h3>
        <p className="text-slate-500 font-medium max-w-md mx-auto">{description}</p>

        <div className="mt-8">
          <button className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold shadow-lg shadow-slate-900/20 active:scale-95 transition-all">
            Browse Files
          </button>
        </div>
      </div>
    </div>
  );
};

export default Dropzone;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import { ProcessingState } from '../types';

declare const PDFLib: any;

const Merge: React.FC = () => {
  const [files, setFiles] = useState<File[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const handleFiles = (newFiles: File[]) => {
    setFiles(prev => [...prev, ...newFiles]);
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const startMerge = async () => {
    if (files.length < 2) return;
    setState({ status: 'processing', progress: 10, message: 'Loading PDF documents...' });

    try {
      const mergedPdf = await PDFLib.PDFDocument.create();

      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        setState(prev => ({ 
          ...prev, 
          progress: Math.round(((i + 1) / files.length) * 100),
          message: `Merging ${file.name}...` 
        }));

        const bytes = await file.arrayBuffer();
        const pdf = await PDFLib.PDFDocument.load(bytes);
        const copiedPages = await mergedPdf.copyPages(pdf, pdf.getPageIndices());
        copiedPages.forEach((page: any) => mergedPdf.addPage(page));
      }

      const mergedBytes = await mergedPdf.save();
      const blob = new Blob([mergedBytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);

      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: 'merged_document.pdf' 
      });
    } catch (error) {
      console.error(error);
      setState({ status: 'error', progress: 0, message: 'Failed to merge PDFs. The file might be corrupted or protected.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 mb-4">Merge PDF</h1>
        <p className="text-slate-600 font-medium">Combine multiple PDF files into one secure document.</p>
      </div>

      {state.status === 'idle' && files.length === 0 && (
        <Dropzone onFilesSelected={handleFiles} multiple title="Drop PDFs to merge" />
      )}

      {files.length > 0 && state.status !== 'success' && (
        <div className="space-y-6">
          <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden">
            <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
              <span className="font-bold text-slate-700">{files.length} Files Selected</span>
              <button 
                onClick={() => setFiles([])}
                className="text-sm font-bold text-rose-500 hover:text-rose-600"
              >
                Clear All
              </button>
            </div>
            <div className="max-h-[400px] overflow-y-auto">
              {files.map((file, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 border-b border-slate-100 last:border-0 hover:bg-slate-50 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center font-bold text-xs uppercase">
                      {file.name.split('.').pop()}
                    </div>
                    <div>
                      <div className="font-bold text-slate-900 text-sm truncate max-w-[200px] md:max-w-md">{file.name}</div>
                      <div className="text-slate-400 text-xs font-medium">{(file.size / 1024).toFixed(1)} KB</div>
                    </div>
                  </div>
                  <button 
                    onClick={() => removeFile(idx)}
                    className="w-8 h-8 rounded-full flex items-center justify-center text-slate-400 hover:bg-rose-50 hover:text-rose-500 transition-all"
                  >
                    <i className="fas fa-times"></i>
                  </button>
                </div>
              ))}
            </div>
            <div className="p-4 bg-slate-50">
               <button 
                onClick={() => document.getElementById('addMoreBtn')?.click()}
                className="w-full py-3 border-2 border-dashed border-slate-300 rounded-2xl text-slate-500 font-bold hover:border-teal-500 hover:text-teal-600 transition-all"
               >
                 <i className="fas fa-plus mr-2"></i> Add More Files
               </button>
               <input id="addMoreBtn" type="file" multiple accept="application/pdf" className="hidden" onChange={(e) => handleFiles(Array.from(e.target.files || []))} />
            </div>
          </div>

          <div className="flex flex-col gap-4">
            <button 
              onClick={startMerge}
              disabled={files.length < 2 || state.status === 'processing'}
              className="w-full bg-teal-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-teal-600/20 active:scale-[0.98] transition-all disabled:opacity-50"
            >
              {state.status === 'processing' ? (
                <span className="flex items-center justify-center gap-3">
                  <i className="fas fa-spinner fa-spin"></i> {state.message}
                </span>
              ) : 'Merge PDFs Now'}
            </button>
            {files.length < 2 && <p className="text-center text-slate-400 text-xs font-bold uppercase tracking-widest">Add at least 2 files to merge</p>}
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white p-12 rounded-[2.5rem] border-2 border-teal-500 text-center shadow-2xl shadow-teal-500/10">
          <div className="w-24 h-24 bg-teal-500 text-white text-4xl rounded-full flex items-center justify-center mx-auto mb-8 animate-bounce">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-900 mb-4">Merge Successful!</h2>
          <p className="text-slate-500 font-medium mb-10">Your merged document is ready for download.</p>

          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a 
              href={state.resultUrl} 
              download={state.resultFileName}
              className="bg-orange-500 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-orange-500/20 hover:scale-105 active:scale-95 transition-all"
            >
              <i className="fas fa-download mr-2"></i> Download PDF
            </a>
            <button 
              onClick={() => { setFiles([]); setState({ status: 'idle', progress: 0 }); }}
              className="bg-slate-100 text-slate-700 px-10 py-4 rounded-2xl font-black text-lg hover:bg-slate-200 transition-all"
            >
              Start Over
            </button>
          </div>
        </div>
      )}

      {state.status === 'error' && (
        <div className="bg-rose-50 p-8 rounded-3xl border border-rose-200 text-center">
          <i className="fas fa-exclamation-circle text-4xl text-rose-500 mb-4"></i>
          <h3 className="text-xl font-bold text-rose-900 mb-2">Oops! Something went wrong</h3>
          <p className="text-rose-700 mb-6">{state.message}</p>
          <button 
            onClick={() => setState({ status: 'idle', progress: 0 })}
            className="bg-rose-500 text-white px-8 py-3 rounded-2xl font-bold"
          >
            Try Again
          </button>
        </div>
      )}
    </div>
  );
};

export default Merge;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import { ProcessingState } from '../types';

declare const pdfjsLib: any;
declare const jspdf: any;

const Compress: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [quality, setQuality] = useState(60); // Default 60% quality

  const handleFile = (files: File[]) => {
    if (files.length > 0) setFile(files[0]);
  };

  const startCompression = async () => {
    if (!file) return;
    setState({ status: 'processing', progress: 5, message: 'Analyzing PDF content...' });

    try {
      const { jsPDF } = jspdf;
      const buffer = await file.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
      const numPages = pdf.numPages;
      const outputPdf = new jsPDF({ unit: 'pt', compress: true });

      for (let i = 1; i <= numPages; i++) {
        setState({ 
          status: 'processing', 
          progress: Math.round((i / numPages) * 100), 
          message: `Compressing Page ${i} of ${numPages}...` 
        });

        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 1.5 }); // High enough for quality, low enough for speed
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        await page.render({ canvasContext: context, viewport }).promise;
        const imgData = canvas.toDataURL('image/jpeg', quality / 100);

        if (i > 1) outputPdf.addPage([viewport.width, viewport.height]);
        else outputPdf.setPage(1);

        outputPdf.addImage(imgData, 'JPEG', 0, 0, viewport.width, viewport.height);
      }

      const blob = outputPdf.output('blob');
      const url = URL.createObjectURL(blob);

      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `compressed_${file.name}`,
        message: `Original: ${(file.size / 1024 / 1024).toFixed(2)}MB -> New: ${(blob.size / 1024 / 1024).toFixed(2)}MB`
      });
    } catch (error) {
      console.error(error);
      setState({ status: 'error', progress: 0, message: 'Failed to compress PDF.' });
    }
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 mb-4">Compress PDF</h1>
        <p className="text-slate-600 font-medium">Reduce your file size while keeping visual integrity.</p>
      </div>

      {state.status === 'idle' && !file && (
        <Dropzone onFilesSelected={handleFile} title="Select PDF to Compress" />
      )}

      {file && state.status !== 'success' && (
        <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-xl">
          <div className="flex items-center gap-4 mb-8 p-4 bg-slate-50 rounded-2xl border border-slate-100">
            <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-xl flex items-center justify-center text-xl">
              <i className="fas fa-file-pdf"></i>
            </div>
            <div className="flex-1 overflow-hidden">
              <div className="font-bold text-slate-900 truncate">{file.name}</div>
              <div className="text-slate-400 text-xs font-bold uppercase tracking-wider">{(file.size / 1024 / 1024).toFixed(2)} MB</div>
            </div>
            <button onClick={() => setFile(null)} className="text-slate-400 hover:text-rose-500">
              <i className="fas fa-times-circle text-xl"></i>
            </button>
          </div>

          <div className="mb-10">
            <div className="flex justify-between items-center mb-4">
              <label className="font-bold text-slate-700">Compression Quality</label>
              <span className="bg-sky-100 text-sky-700 px-3 py-1 rounded-lg font-black text-sm">{quality}%</span>
            </div>
            <input 
              type="range" 
              min="10" 
              max="90" 
              value={quality} 
              onChange={(e) => setQuality(Number(e.target.value))}
              className="w-full h-3 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-sky-500" 
            />
            <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">
              <span>Super Small</span>
              <span>Best Quality</span>
            </div>
          </div>

          <button 
            onClick={startCompression}
            disabled={state.status === 'processing'}
            className="w-full bg-sky-500 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-sky-500/20 hover:bg-sky-600 active:scale-[0.98] transition-all disabled:opacity-50"
          >
            {state.status === 'processing' ? (
              <span className="flex items-center justify-center gap-3">
                <i className="fas fa-circle-notch fa-spin"></i> {state.message}
              </span>
            ) : 'Compress Now'}
          </button>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white p-12 rounded-[2.5rem] border-2 border-sky-500 text-center shadow-2xl shadow-sky-500/10">
          <div className="w-20 h-20 bg-sky-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-900 mb-2">Perfectly Optimized!</h2>
          <div className="inline-block px-4 py-2 bg-sky-50 text-sky-700 rounded-xl font-bold text-sm mb-10">
            {state.message}
          </div>

          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a 
              href={state.resultUrl} 
              download={state.resultFileName}
              className="bg-orange-500 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-orange-500/20 transition-all"
            >
              <i className="fas fa-download mr-2"></i> Download File
            </a>
            <button 
              onClick={() => { setFile(null); setState({ status: 'idle', progress: 0 }); }}
              className="bg-slate-100 text-slate-700 px-10 py-4 rounded-2xl font-black text-lg"
            >
              Compress Another
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Compress;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import Dropzone from '../components/Dropzone';

declare const pdfjsLib: any;

const AIChat: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [messages, setMessages] = useState<{role: 'user' | 'ai', content: string}[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [docContext, setDocContext] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  const extractText = async (pdfFile: File) => {
    setIsTyping(true);
    setMessages([{ role: 'ai', content: `Analyzing "${pdfFile.name}"... Give me a second to read through it.` }]);

    try {
      const buffer = await pdfFile.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
      let fullText = "";

      const maxPages = Math.min(pdf.numPages, 20); // Limit context for performance
      for (let i = 1; i <= maxPages; i++) {
        const page = await pdf.getPage(i);
        const textContent = await page.getTextContent();
        const pageText = textContent.items.map((item: any) => item.str).join(" ");
        fullText += pageText + "\n";
      }

      setDocContext(fullText);
      setMessages(prev => [
        ...prev, 
        { role: 'ai', content: `I've finished reading the first ${maxPages} pages. What would you like to know about this document?` }
      ]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', content: "Sorry, I had trouble reading this PDF. Is it encrypted or corrupted?" }]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
