declare const jspdf: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const scanner = useRef<any>(null);

  useEffect(() => {
    scanner.current = new jscanify();
    return () => stopCamera();
  }, []);

  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setState({ status: 'loading', progress: 0 });
    } catch (err) {
      console.error(err);
      alert("Please allow camera access to scan documents.");
    }
  };

  const stopCamera = () => {
    stream?.getTracks().forEach(track => track.stop());
    setStream(null);
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx?.drawImage(videoRef.current, 0, 0);

    const resultCanvas = scanner.current.extractPaper(canvas, 1000, 1414); // A4 ratio
    setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg')]);
  };

  const generatePDF = () => {
    const { jsPDF } = jspdf;
    const doc = new jsPDF('p', 'mm', 'a4');
    capturedImages.forEach((img, idx) => {
      if (idx > 0) doc.addPage();
      doc.addImage(img, 'JPEG', 0, 0, 210, 297);
    });
    const blob = doc.output('blob');
    const url = URL.createObjectURL(blob);
    setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: 'scanned_document.pdf' });
    stopCamera();
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-8">
        <h1 className="text-4xl font-extrabold text-slate-900 mb-2">Scan to PDF</h1>
        <p className="text-slate-500 font-medium">Convert physical documents to PDF using your camera.</p>
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white p-20 rounded-[3rem] border-4 border-dashed border-slate-200 text-center">
          <div className="w-24 h-24 bg-teal-50 text-teal-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-8">
            <i className="fas fa-camera"></i>
          </div>
          <button onClick={startCamera} className="bg-teal-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-teal-600/20">
            Open Camera
          </button>
        </div>
      )}

      {stream && (
        <div className="relative rounded-3xl overflow-hidden bg-black shadow-2xl aspect-[3/4] md:aspect-video">
          <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center gap-6">
            <button onClick={captureFrame} className="w-20 h-20 bg-white border-8 border-teal-500/30 rounded-full flex items-center justify-center text-teal-600 text-2xl active:scale-90 transition-all">
              <i className="fas fa-camera"></i>
            </button>
            {capturedImages.length > 0 && (
              <button onClick={generatePDF} className="bg-teal-600 text-white px-8 py-4 rounded-2xl font-bold shadow-xl">
                Done ({capturedImages.length})
              </button>
            )}
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white p-12 rounded-[2.5rem] border-2 border-teal-500 text-center">
          <div className="w-20 h-20 bg-teal-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-900 mb-10">Scan Complete!</h2>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-orange-500/20">
              Download PDF
            </a>
            <button onClick={() => { setCapturedImages([]); setState({ status: 'idle', progress: 0 }); }} className="bg-slate-100 text-slate-700 px-10 py-4 rounded-2xl font-black text-lg">
              New Scan
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Scan;

