import React, { useRef, useState } from 'react';

interface DropzoneProps {
  onFilesSelected: (files: File[]) => void;
  accept?: string;
  multiple?: boolean;
  title?: string;
  description?: string;
  icon?: string;
}

const Dropzone: React.FC<DropzoneProps> = ({ 
  onFilesSelected, 
  accept = "application/pdf", 
  multiple = false,
  title = "Select or Drag & Drop PDF",
  description = "Processing happens 100% locally on your machine.",
  icon = "fa-cloud-upload-alt"
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      onFilesSelected(Array.from(e.target.files));
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files) {
      const files = Array.from(e.dataTransfer.files) as File[];
      const filtered = accept.includes('*') 
        ? files 
        : files.filter(f => accept.split(',').some(a => f.type.includes(a.trim().replace('*', ''))));
      onFilesSelected(filtered);
    }
  };

  return (
    <div 
      className={`relative group cursor-pointer transition-all ${isDragging ? 'scale-[0.99]' : ''}`}
      onClick={() => inputRef.current?.click()}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={handleDrop}
    >
      <input 
        type="file" 
        ref={inputRef} 
        onChange={handleFileChange} 
        accept={accept} 
        multiple={multiple} 
        className="hidden" 
      />
      <div className={`
        border-4 border-dashed rounded-[2.5rem] p-16 text-center transition-all duration-300
        ${isDragging 
          ? 'border-teal-500 bg-teal-50/50 dark:bg-teal-900/10 shadow-inner' 
          : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-teal-400 group-hover:bg-slate-50/50 dark:group-hover:bg-slate-800/50 group-hover:shadow-xl group-hover:shadow-slate-200/50 dark:group-hover:shadow-black/50'}
      `}>
        <div className={`
          w-24 h-24 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-8 transition-all
          ${isDragging ? 'bg-teal-500 text-white scale-110' : 'bg-slate-100 dark:bg-slate-800 text-slate-400 group-hover:bg-teal-50 dark:group-hover:bg-teal-900/30 group-hover:text-teal-600 dark:group-hover:text-teal-400 group-hover:-translate-y-2'}
        `}>
          <i className={`fas ${icon}`}></i>
        </div>
        <h3 className="text-2xl font-extrabold text-slate-900 dark:text-white mb-2">{title}</h3>
        <p className="text-slate-500 dark:text-slate-400 font-medium max-w-md mx-auto">{description}</p>

        <div className="mt-8">
          <button className="bg-slate-900 dark:bg-slate-100 dark:text-slate-900 text-white px-8 py-3 rounded-2xl font-bold shadow-lg shadow-slate-900/20 active:scale-95 transition-all">
            Browse Files
          </button>
        </div>
      </div>
    </div>
  );
};

