import React, { useRef, useState } from 'react';

interface DropzoneProps {
  onFilesSelected: (files: File[]) => void;
  accept?: string;
  multiple?: boolean;
  title?: string;
  description?: string;
  icon?: string;
}

const Dropzone: React.FC<DropzoneProps> = ({ 
  onFilesSelected, 
  accept = "application/pdf", 
  multiple = false,
  title = "Select PDF",
  description = "Processed locally on your device.",
  icon = "fa-file-upload"
}) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      onFilesSelected(Array.from(e.target.files));
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files) {
      const files = Array.from(e.dataTransfer.files) as File[];
      const filtered = accept.includes('*') 
        ? files 
        : files.filter(f => accept.split(',').some(a => f.type.includes(a.trim().replace('*', ''))));
      onFilesSelected(filtered);
    }
  };

  return (
    <div 
      className="max-w-xl mx-auto"
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={handleDrop}
    >
      <input 
        type="file" 
        ref={inputRef} 
        onChange={handleFileChange} 
        accept={accept} 
        multiple={multiple} 
        className="hidden" 
      />
      <div 
        onClick={() => inputRef.current?.click()}
        className={`
          cursor-pointer border-2 border-dashed rounded-3xl p-10 text-center transition-all duration-300
          ${isDragging 
            ? 'border-teal-500 bg-teal-50/50 dark:bg-teal-900/10' 
            : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-teal-400 hover:bg-slate-50 dark:hover:bg-slate-800/50'}
        `}
      >
        <div className={`
          w-16 h-16 rounded-2xl flex items-center justify-center text-2xl mx-auto mb-6 transition-all
          ${isDragging ? 'bg-teal-500 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}
        `}>
          <i className={`fas ${icon}`}></i>
        </div>
        <h3 className="text-xl font-black text-slate-900 dark:text-white mb-1">{title}</h3>
        <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider mb-6">{description}</p>

        <button className="bg-slate-900 dark:bg-slate-100 dark:text-slate-900 text-white px-8 py-2.5 rounded-xl text-sm font-black shadow-lg active:scale-95 transition-all">
          Browse Files
        </button>
      </div>
    </div>
  );
};

export default Dropzone;

