import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import { ProcessingState } from '../types';

const Rotate: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [angle, setAngle] = useState(90);

  const startRotation = async () => {
    if (!file) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) {
      setState({ status: 'error', progress: 0, message: 'PDF Library not loaded.' });
      return;
    }

    setState({ status: 'processing', progress: 50, message: 'Rotating pages...' });

    try {
      const { degrees } = PDFLib;
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const pages = pdfDoc.getPages();

      pages.forEach((page: any) => {
        const rotation = page.getRotation().angle;
        page.setRotation(degrees(rotation + angle));
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);

      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `rotated_${file.name}` 
      });
    } catch (error) {
      console.error('Rotation Error:', error);
      setState({ status: 'error', progress: 0, message: 'Failed to rotate PDF.' });
    }
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4">Rotate PDF</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Rotate every page in your document instantly.</p>
      </div>

      {state.status === 'idle' && !file && (
        <Dropzone onFilesSelected={(files) => setFile(files[0])} title="Select PDF to Rotate" />
      )}

      {file && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl text-center">
          <div className="w-20 h-20 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 text-3xl rounded-3xl flex items-center justify-center mx-auto mb-6">
            <i className="fas fa-redo"></i>
          </div>
          <h3 className="text-xl font-bold text-slate-900 dark:text-slate-100 mb-8 truncate">{file.name}</h3>

          <div className="flex justify-center gap-4 mb-10">
            {[90, 180, 270].map(deg => (
              <button 
                key={deg}
                onClick={() => setAngle(deg)}
                className={`px-6 py-3 rounded-xl font-bold transition-all ${angle === deg ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
              >
                {deg}°
              </button>
            ))}
          </div>

          <button 
            onClick={startRotation}
            disabled={state.status === 'processing'}
            className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-indigo-600/20 active:scale-95 transition-all"
          >
            {state.status === 'processing' ? 'Processing...' : 'Rotate Pages'}
          </button>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[2.5rem] border-2 border-indigo-500 text-center shadow-2xl">
          <div className="w-20 h-20 bg-indigo-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-10">Rotation Complete!</h2>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-lg active:scale-95 transition-all">
              Download PDF
            </a>
            <button onClick={() => { setFile(null); setState({ status: 'idle', progress: 0 }); }} className="bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 px-10 py-4 rounded-2xl font-black text-lg">
              Start Over
            </button>
          </div>
        </div>
      )}

      {state.status === 'error' && (
        <div className="mt-6 p-4 bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl text-rose-600 dark:text-rose-400 font-bold text-center">
          {state.message}
        </div>
      )}
    </div>
  );
};

export default Rotate;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import { ProcessingState } from '../types';

const Protect: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [password, setPassword] = useState('');
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const protect = async () => {
    if (!file || !password) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) {
      setState({ status: 'error', progress: 0, message: 'PDF Library not loaded.' });
      return;
    }

    setState({ status: 'processing', progress: 50, message: 'Encrypting...' });

    try {
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);

      // Note: Encryption in browser depends on the specific build of pdf-lib
      // We use the most robust save options available for the CDN version
      const pdfBytes = await pdfDoc.save({ 
        userPassword: password,
        ownerPassword: password,
        permissions: {
          printing: 'highResolution',
          modifying: false,
          copying: false,
          annotating: true,
          fillingForms: true,
          contentAccessibility: true,
          documentAssembly: true,
        }
      });

      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: `protected_${file.name}` });
    } catch (error) {
      console.error('Protection Error:', error);
      setState({ status: 'error', progress: 0, message: 'Encryption failed. Ensure the file is valid.' });
    }
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4">Protect PDF</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Add password protection to your document.</p>
      </div>

      {state.status === 'idle' && !file && <Dropzone onFilesSelected={(f) => setFile(f[0])} />}

      {file && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
           <div className="mb-8">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">Set Password</label>
              <input 
                type="password" 
                value={password} 
                onChange={e => setPassword(e.target.value)}
                className="w-full px-6 py-4 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950 focus:border-teal-500 outline-none text-slate-900 dark:text-white"
                placeholder="Enter strong password..."
              />
           </div>
           <button onClick={protect} className="w-full bg-slate-900 dark:bg-teal-600 text-white py-4 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl">
             Apply Protection
           </button>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[2.5rem] border-2 border-slate-900 dark:border-teal-500 text-center shadow-2xl">
           <div className="text-5xl mb-6"><i className="fas fa-lock text-teal-500"></i></div>
           <h2 className="text-3xl font-black mb-8 dark:text-white">PDF Locked!</h2>
           <div className="flex flex-col gap-4">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-lg active:scale-95">
              Download Protected PDF
            </a>
            <button onClick={() => { setFile(null); setPassword(''); setState({status: 'idle', progress: 0})}} className="text-slate-400 font-bold uppercase text-xs">Protect Another</button>
           </div>
        </div>
      )}

      {state.status === 'error' && (
        <div className="mt-6 p-4 bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl text-rose-600 dark:text-rose-400 font-bold text-center">
          {state.message}
        </div>
      )}
    </div>
  );
};

export default Protect;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import { ProcessingState } from '../types';

const Watermark: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [text, setText] = useState('CONFIDENTIAL');
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const apply = async () => {
    if (!file || !text) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) {
      setState({ status: 'error', progress: 0, message: 'PDF Library not loaded.' });
      return;
    }

    setState({ status: 'processing', progress: 50, message: 'Applying watermark...' });

    try {
      const { rgb, degrees, StandardFonts } = PDFLib;
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const helveticaFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
      const pages = pdfDoc.getPages();

      pages.forEach((page: any) => {
        const { width, height } = page.getSize();
        page.drawText(text, {
          x: width / 2 - 150,
          y: height / 2 - 50,
          size: 60,
          font: helveticaFont,
          color: rgb(0.7, 0.7, 0.7),
          rotate: degrees(45),
          opacity: 0.3,
        });
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: `watermarked_${file.name}` });
    } catch (err) {
      console.error('Watermark Error:', err);
      setState({ status: 'error', progress: 0, message: 'Failed to apply watermark.' });
    }
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4">Watermark</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Add text stamps to your document for security.</p>
      </div>

      {state.status === 'idle' && !file && <Dropzone onFilesSelected={(f) => setFile(f[0])} />}

      {file && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
           <div className="mb-8">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2 text-left">Watermark Text</label>
              <input 
                type="text" 
                value={text} 
                onChange={e => setText(e.target.value)}
                className="w-full px-6 py-4 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950 focus:border-orange-500 outline-none text-slate-900 dark:text-white"
                placeholder="CONFIDENTIAL, COPY, DRAFT..."
              />
           </div>
           <button onClick={apply} className="w-full bg-orange-500 text-white py-4 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl shadow-orange-500/10">
             Stamp All Pages
           </button>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[2.5rem] border-2 border-orange-500 text-center shadow-2xl">
           <div className="text-5xl mb-6 text-orange-500"><i className="fas fa-stamp"></i></div>
           <h2 className="text-3xl font-black mb-8 dark:text-white">Watermark Applied!</h2>
           <div className="flex flex-col gap-4">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-slate-900 dark:bg-teal-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-lg active:scale-95">
              Download PDF
            </a>
            <button onClick={() => { setFile(null); setState({status: 'idle', progress: 0})}} className="text-slate-400 font-bold uppercase text-xs">Add to Another</button>
           </div>
        </div>
      )}

      {state.status === 'error' && (
        <div className="mt-6 p-4 bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl text-rose-600 dark:text-rose-400 font-bold text-center">
          {state.message}
        </div>
      )}
    </div>
  );
};

