import { ProcessingState } from '../types';

const Numbering: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [pos, setPos] = useState<'bc' | 'br' | 'bl' | 'tc' | 'tr' | 'tl'>('bc');
  const [color, setColor] = useState('#64748b');
  const [fontSize, setFontSize] = useState(10);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const addNumbers = async () => {
    if (!file) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) return;

    setState({ status: 'processing', progress: 50, message: 'Adding page numbers...' });

    try {
      const { rgb, StandardFonts } = PDFLib;
      const hexToRgb = (hex: string) => {
        const r = parseInt(hex.slice(1, 3), 16) / 255;
        const g = parseInt(hex.slice(3, 5), 16) / 255;
        const b = parseInt(hex.slice(5, 7), 16) / 255;
        return rgb(r, g, b);
      };

      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const pages = pdfDoc.getPages();

      pages.forEach((page: any, i: number) => {
        const { width, height } = page.getSize();
        const text = `Page ${i + 1} of ${pages.length}`;
        const textWidth = helveticaFont.widthOfTextAtSize(text, fontSize);

        let x = width / 2 - textWidth / 2; // Default center
        let y = 25; // Default bottom

        if (pos === 'bl') x = 30;
        if (pos === 'br') x = width - textWidth - 30;
        if (pos === 'tc' || pos === 'tl' || pos === 'tr') y = height - 35;
        if (pos === 'tl') x = 30;
        if (pos === 'tr') x = width - textWidth - 30;

        page.drawText(text, {
          x, y,
          size: fontSize,
          font: helveticaFont,
          color: hexToRgb(color),
        });
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: URL.createObjectURL(blob), 
        resultFileName: `numbered_${file.name}` 
      });
    } catch (err) {
      console.error(err);
      setState({ status: 'error', message: 'Numbering failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4">Page Numbering</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Add professional labels with precision styling.</p>
      </div>

      {!file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-list-ol" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
           <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <PDFPreview file={file} className="aspect-[3/4]" />
             <button onClick={() => setFile(null)} className="w-full mt-4 text-[10px] font-black text-rose-500 uppercase tracking-widest">Remove File</button>
           </div>

           <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl space-y-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Placement</label>
                <div className="grid grid-cols-3 gap-2">
                   {[
                     { id: 'tl', icon: 'fa-arrow-up-left' }, { id: 'tc', icon: 'fa-arrow-up' }, { id: 'tr', icon: 'fa-arrow-up-right' },
                     { id: 'bl', icon: 'fa-arrow-down-left' }, { id: 'bc', icon: 'fa-arrow-down' }, { id: 'br', icon: 'fa-arrow-down-right' }
                   ].map(item => (
                     <button 
                       key={item.id} 
                       onClick={() => setPos(item.id as any)}
                       className={`p-4 rounded-xl border-2 transition-all ${pos === item.id ? 'border-teal-500 bg-teal-50 text-teal-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}
                     >
                       <i className={`fas ${item.icon}`}></i>
                     </button>
                   ))}
                </div>
              </div>

              <div className="flex gap-6">
                 <div className="flex-1">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Color</label>
                    <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-12 rounded-xl cursor-pointer bg-transparent border-0" />
                 </div>
                 <div className="flex-1">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Font Size ({fontSize}pt)</label>
                    <input type="range" min="6" max="24" value={fontSize} onChange={e => setFontSize(parseInt(e.target.value))} className="w-full h-12 accent-teal-500" />
                 </div>
              </div>

              <button onClick={addNumbers} className="w-full bg-slate-900 dark:bg-teal-600 text-white py-5 rounded-[2rem] font-black text-lg shadow-xl active:scale-95 transition-all">
                Add Page Numbers
              </button>
           </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3rem] border-2 border-slate-900 dark:border-teal-500 text-center shadow-2xl animate-in zoom-in duration-300">
           <div className="text-6xl text-teal-500 mb-8"><i className="fas fa-list-ol"></i></div>
           <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-10">Numbers Added!</h2>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">Download PDF</a>
