  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const addNumbers = async () => {
    if (!file) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) return;

    setState({ status: 'processing', progress: 50, message: 'Adding page numbers...' });

    try {
      const { rgb, StandardFonts } = PDFLib;
      const hexToRgb = (hex: string) => {
        const r = parseInt(hex.slice(1, 3), 16) / 255;
        const g = parseInt(hex.slice(3, 5), 16) / 255;
        const b = parseInt(hex.slice(5, 7), 16) / 255;
        return rgb(r, g, b);
      };

      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const pages = pdfDoc.getPages();

      pages.forEach((page: any, i: number) => {
        const { width, height } = page.getSize();
        const text = `Page ${i + 1} of ${pages.length}`;
        const textWidth = helveticaFont.widthOfTextAtSize(text, fontSize);

        let x = width / 2 - textWidth / 2; // Default center
        let y = 30; // Default bottom

        if (pos === 'bl') x = 40;
        if (pos === 'br') x = width - textWidth - 40;
        if (pos === 'tc' || pos === 'tl' || pos === 'tr') y = height - 40;
        if (pos === 'tl') x = 40;
        if (pos === 'tr') x = width - textWidth - 40;

        page.drawText(text, {
          x, y,
          size: fontSize,
          font: helveticaFont,
          color: hexToRgb(color),
        });
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: URL.createObjectURL(blob), 
        resultFileName: `numbered_${file.name}` 
      });
    } catch (err) {
      console.error(err);
      setState({ status: 'error', message: 'Numbering failed.' });
    }
  };

  const positions = [
    { id: 'tl', label: 'Top Left' }, { id: 'tc', label: 'Top Center' }, { id: 'tr', label: 'Top Right' },
    { id: 'bl', label: 'Bottom Left' }, { id: 'bc', label: 'Bottom Center' }, { id: 'br', label: 'Bottom Right' }
  ];

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4 uppercase tracking-tight">Page Numbering</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Add professional labels with precision styling.</p>
      </div>

      {!file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-list-ol" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
           <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <div className="mb-4 flex justify-between items-center px-2">
                <span className="text-[10px] font-black uppercase text-teal-600 tracking-widest">Document Layout</span>
                <button onClick={() => setFile(null)} className="text-slate-400 text-[10px] font-black uppercase">Remove</button>
             </div>
             <PDFPreview file={file} className="aspect-[3/4]" />
           </div>

           <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl space-y-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Select Placement</label>
                <div className="grid grid-cols-3 gap-2">
                   {positions.map(item => (
                     <button 
                       key={item.id} 
                       onClick={() => setPos(item.id as any)}
                       className={`h-16 rounded-xl border-2 transition-all flex flex-col items-center justify-center gap-1 ${pos === item.id ? 'border-teal-500 bg-teal-50 dark:bg-teal-900/20 text-teal-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}
                     >
                       <div className={`w-3 h-3 rounded-full border-2 ${pos === item.id ? 'bg-teal-500 border-teal-600' : 'border-slate-200 dark:border-slate-700'}`}></div>
                       <span className="text-[8px] font-black uppercase tracking-widest text-center px-1">{item.label}</span>
                     </button>
                   ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Text Color</label>
                    <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-14 rounded-xl cursor-pointer bg-slate-50 dark:bg-slate-950 p-1 border border-slate-200 dark:border-slate-800" />
                 </div>
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Font Size: {fontSize}pt</label>
                    <input type="range" min="6" max="24" value={fontSize} onChange={e => setFontSize(parseInt(e.target.value))} className="w-full h-14 accent-teal-500" />
                 </div>
              </div>

              <button onClick={addNumbers} className="w-full bg-slate-900 dark:bg-teal-600 text-white py-5 rounded-[2rem] font-black text-lg shadow-xl active:scale-95 transition-all">
                Add Page Numbers
              </button>
           </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3rem] border-2 border-slate-900 dark:border-teal-500 text-center shadow-2xl animate-in zoom-in duration-300">
           <div className="text-6xl text-teal-500 mb-8"><i className="fas fa-list-ol"></i></div>
           <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-10">Numbers Added!</h2>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">Download PDF</a>
              <button onClick={() => { setFile(null); setState({status:'idle', progress: 0}) }} className="bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 px-12 py-5 rounded-2xl font-black text-xl">Start New</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default Numbering;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import PDFPreview from '../components/PDFPreview';
import { ProcessingState } from '../types';

declare const PDFLib: any;

const CropPDF: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [margin, setMargin] = useState(20);

  const applyCrop = async () => {
    if (!file) return;
    setState({ status: 'processing', progress: 50, message: 'Cropping margins...' });

    try {
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const pages = pdfDoc.getPages();

      pages.forEach((page: any) => {
        const { width, height } = page.getSize();
        // Adjust CropBox - shrinking the viewable area by the margin on all sides
        // Ensure margin isn't larger than half the dimension
        const safeMargin = Math.min(margin, width / 2 - 5, height / 2 - 5);
        page.setCropBox(safeMargin, safeMargin, width - safeMargin * 2, height - safeMargin * 2);
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);
      setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: `cropped_${file.name}` });
    } catch (err) {
      console.error(err);
      setState({ status: 'error', progress: 0, message: 'Cropping failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4 uppercase tracking-tight">Crop PDF</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Trim white margins or focus on specific content areas.</p>
      </div>

      {!file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-crop-alt" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl relative overflow-hidden">
             <div className="flex justify-between items-center mb-4 px-2">
                <span className="text-[10px] font-black uppercase text-teal-600 tracking-widest">Crop Guide</span>
                <button onClick={() => setFile(null)} className="text-slate-400 text-[10px] font-black uppercase">Change</button>
             </div>
             <div className="relative">
                <PDFPreview file={file} className="aspect-[3/4]" />
                {/* Visual Overlay of the crop */}
                <div 
                  className="absolute inset-0 border-teal-500/50 bg-slate-900/10 pointer-events-none transition-all duration-300"
                  style={{ borderWidth: `${margin / 3}px`, borderStyle: 'solid' }}
                ></div>
             </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl flex flex-col justify-center">
             <div className="mb-10">
                <div className="flex justify-between items-center mb-4 px-2">
                  <label className="text-[10px] font-black text-teal-600 uppercase tracking-widest">Margin to Trim (Points)</label>
                  <span className="font-black text-slate-900 dark:text-white bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-lg">{margin}pt</span>
                </div>
                <input 
                  type="range" 
                  min="0" 
                  max="100" 
                  value={margin} 
                  onChange={e => setMargin(parseInt(e.target.value))}
                  className="w-full h-4 bg-slate-100 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-teal-600"
                />
                <div className="flex justify-between mt-3 text-[8px] font-black uppercase text-slate-400 tracking-widest">
                  <span>No Crop</span>
                  <span>Deep Trim</span>
                </div>
             </div>

             <button onClick={applyCrop} className="w-full bg-teal-600 text-white py-5 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl shadow-teal-500/20">
               {state.status === 'processing' ? <i className="fas fa-spinner fa-spin mr-2"></i> : 'Apply Crop'}
             </button>
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3rem] border-2 border-teal-500 text-center shadow-2xl animate-in zoom-in duration-300">
           <div className="text-5xl mb-6 text-teal-500 animate-bounce"><i className="fas fa-crop"></i></div>
           <h2 className="text-3xl font-black mb-8 dark:text-white">PDF Cropped!</h2>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">
              Download Cropped PDF
            </a>
            <button onClick={() => { setFile(null); setState({status:'idle', progress: 0}) }} className="bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 px-12 py-5 rounded-2xl font-black text-xl">Start New</button>
           </div>
        </div>
      )}
