import React, { useState, useRef, useEffect } from 'react';
import { ProcessingState } from '../types';

declare const jscanify: any;
declare const jspdf: any;
declare const cv: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [isScannerReady, setIsScannerReady] = useState(false);
  const scanner = useRef<any>(null);

  useEffect(() => {
    let checkInterval: any;

    const initScanner = () => {
      // Robust check for OpenCV readiness
      if (typeof jscanify !== 'undefined' && typeof cv !== 'undefined' && cv.Mat) {
        try {
          scanner.current = new jscanify();
          setIsScannerReady(true);
          console.log("Scanner engine ready.");
          if (checkInterval) clearInterval(checkInterval);
        } catch (e) {
          console.warn("Retrying scanner init...");
        }
      }
    };

    checkInterval = setInterval(initScanner, 1000);
    initScanner();

    return () => {
      if (checkInterval) clearInterval(checkInterval);
      stopCamera();
    };
  }, []);

  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment',
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        } 
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play();
        };
      }
      setState({ status: 'processing', progress: 0, message: 'Camera active' });
    } catch (err) {
      console.error(err);
      alert("Camera access denied. Ensure you have granted permissions.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current || !scanner.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    try {
      // Auto extraction to A4
      const resultCanvas = scanner.current.extractPaper(canvas, 1200, 1697);
      setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg', 0.9)]);
    } catch (e) {
      console.warn("Extraction failed, using full frame:", e);
      setCapturedImages(prev => [...prev, canvas.toDataURL('image/jpeg', 0.9)]);
    }
  };

  const generatePDF = () => {
    if (capturedImages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Compiling PDF...' });

    try {
      const { jsPDF } = jspdf;
      const doc = new jsPDF('p', 'mm', 'a4');

      capturedImages.forEach((img, idx) => {
        if (idx > 0) doc.addPage();
        doc.addImage(img, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
      });

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `scan_${Date.now()}.pdf` 
      });
      stopCamera();
    } catch (error) {
      console.error(error);
      setState({ status: 'error', progress: 0, message: 'Generation failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-8">
        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-2 uppercase tracking-tight">Scan to PDF</h1>
        <p className="text-slate-500 dark:text-slate-400 font-medium">Capture documents with auto-edge detection.</p>

        {!isScannerReady && state.status !== 'success' && (
          <div className="mt-4 inline-flex items-center gap-2 px-6 py-2 bg-orange-50 dark:bg-orange-900/20 text-orange-600 dark:text-orange-400 rounded-full text-[10px] font-black uppercase tracking-widest border border-orange-100 dark:border-orange-800 animate-pulse">
            <i className="fas fa-spinner fa-spin"></i> Preparing Scanner Engine...
          </div>
        )}
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-20 rounded-[3rem] border-4 border-dashed border-slate-200 dark:border-slate-800 text-center shadow-2xl flex flex-col items-center">
          <div className="w-24 h-24 bg-teal-50 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-3xl flex items-center justify-center text-4xl mb-8 shadow-inner">
            <i className="fas fa-camera"></i>
          </div>
          <button 
            onClick={startCamera} 
            disabled={!isScannerReady}
            className="bg-teal-600 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl shadow-teal-500/20 disabled:opacity-50 transition-all active:scale-95"
          >
            Open Camera
          </button>
          <p className="mt-6 text-[10px] text-slate-400 font-black uppercase tracking-[0.3em]">Privacy Guaranteed • Local Processing Only</p>
        </div>
      )}

      {stream && (
        <div className="relative rounded-[3rem] overflow-hidden bg-black shadow-2xl aspect-[3/4] max-w-lg mx-auto ring-[12px] ring-white dark:ring-slate-900">
          <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          <div className="absolute inset-0 border-[30px] border-black/30 pointer-events-none">
             <div className="w-full h-full border-2 border-dashed border-white/40 rounded-2xl"></div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-6">
            <button 
              onClick={captureFrame} 
              className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-teal-600 text-2xl active:scale-90 transition-all shadow-2xl border-4 border-teal-500/20"
            >
              <i className="fas fa-camera"></i>
            </button>

            {capturedImages.length > 0 && (
              <button 
                onClick={generatePDF} 
                className="bg-teal-600 text-white px-8 py-5 rounded-2xl font-black text-sm shadow-xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4"
              >
                Finish PDF <span className="bg-white/20 px-2.5 py-1 rounded-lg text-[10px]">{capturedImages.length}</span>
              </button>
            )}

            <button onClick={stopCamera} className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all">
               <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      {capturedImages.length > 0 && (
        <div className="mt-12 max-w-2xl mx-auto">
          <div className="flex gap-4 overflow-x-auto pb-6 px-4 no-scrollbar">
            {capturedImages.map((img, i) => (
              <div key={i} className="flex-shrink-0 w-28 aspect-[3/4] rounded-2xl border-4 border-white dark:border-slate-800 overflow-hidden relative group shadow-xl transition-all hover:scale-105">
                <img src={img} className="w-full h-full object-cover" />
                <button 
                  onClick={() => setCapturedImages(prev => prev.filter((_, idx) => idx !== i))}
                  className="absolute inset-0 bg-rose-500/90 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-lg"
                >
                  <i className="fas fa-trash"></i>
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3rem] border-2 border-teal-500 text-center shadow-2xl animate-in zoom-in duration-300">
          <div className="w-24 h-24 bg-teal-500 text-white text-4xl rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-teal-500/20">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-4xl font-black dark:text-white mb-10">Scan Complete!</h2>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">
              Download PDF
            </a>
            <button onClick={() => { setCapturedImages([]); setState({ status: 'idle', progress: 0 }); }} className="bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 px-12 py-5 rounded-2xl font-black text-xl">
              New Scan
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import PDFPreview from '../components/PDFPreview';
import { ProcessingState } from '../types';

declare const pdfjsLib: any;
declare const jspdf: any;

const Protect: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [password, setPassword] = useState('');
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const protect = async () => {
    if (!file || !password) return;

    setState({ status: 'processing', progress: 10, message: 'Applying encryption...' });

    try {
      const { jsPDF } = jspdf;
      const arrayBuffer = await file.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      const numPages = pdf.numPages;

      // We recreate the PDF with encryption. 
      // jsPDF encryption works best when pages are added as images to ensure cross-reader compatibility for passwords.
      const doc = new jsPDF({
        encryption: {
          userPassword: password,
          ownerPassword: password,
          userPermissions: ['print', 'modify', 'copy', 'annotating']
        }
      });

      for (let i = 1; i <= numPages; i++) {
        setState({ 
          status: 'processing', 
          progress: Math.round((i / numPages) * 100), 
          message: `Encrypting page ${i}...` 
        });

        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 2.0 });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        if (!context) continue;

        canvas.height = viewport.height;
        canvas.width = viewport.width;

        await page.render({ canvasContext: context, viewport }).promise;
        const imgData = canvas.toDataURL('image/jpeg', 0.9);

        if (i > 1) doc.addPage([viewport.width, viewport.height]);
        else {
          doc.deletePage(1);
          doc.addPage([viewport.width, viewport.height]);
        }

        doc.addImage(imgData, 'JPEG', 0, 0, viewport.width, viewport.height);
      }

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: `protected_${file.name}` });
    } catch (error) {
      console.error('Protection Error:', error);
      setState({ status: 'error', progress: 0, message: 'Encryption failed. Please check your browser compatibility.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-4 uppercase tracking-tighter">Protect PDF</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Add secure password protection locally.</p>
      </div>

      {state.status === 'idle' && !file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-lock" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <PDFPreview file={file} className="aspect-[3/4]" />
             <div className="mt-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">{file.name}</div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl flex flex-col justify-center">
             <div className="mb-8">
