import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import PDFPreview from '../components/PDFPreview';
import { ProcessingState } from '../types';

const Numbering: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [pos, setPos] = useState<'bc' | 'br' | 'bl' | 'tc' | 'tr' | 'tl'>('bc');
  const [color, setColor] = useState('#64748b');
  const [fontSize, setFontSize] = useState(10);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const addNumbers = async () => {
    if (!file) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) return;

    setState({ status: 'processing', progress: 50, message: 'Numbering pages...' });

    try {
      const { rgb, StandardFonts } = PDFLib;
      const hexToRgb = (hex: string) => {
        const r = parseInt(hex.slice(1, 3), 16) / 255;
        const g = parseInt(hex.slice(3, 5), 16) / 255;
        const b = parseInt(hex.slice(5, 7), 16) / 255;
        return rgb(r, g, b);
      };

      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const pages = pdfDoc.getPages();

      pages.forEach((page: any, i: number) => {
        const { width, height } = page.getSize();
        const text = `${i + 1}`;
        const textWidth = helveticaFont.widthOfTextAtSize(text, fontSize);

        let x = width / 2 - textWidth / 2;
        let y = 30;

        if (pos === 'bl') x = 40;
        if (pos === 'br') x = width - textWidth - 40;
        if (pos === 'tc' || pos === 'tl' || pos === 'tr') y = height - 40;
        if (pos === 'tl') x = 40;
        if (pos === 'tr') x = width - textWidth - 40;

        page.drawText(text, {
          x, y,
          size: fontSize,
          font: helveticaFont,
          color: hexToRgb(color),
        });
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: URL.createObjectURL(blob), 
        resultFileName: `numbered_${file.name}` 
      });
    } catch (err) {
      console.error(err);
      setState({ status: 'error', message: 'Process failed.' });
    }
  };

  const positions = [
    { id: 'tl', label: 'Top Left' }, { id: 'tc', label: 'Top Center' }, { id: 'tr', label: 'Top Right' },
    { id: 'bl', label: 'Bottom Left' }, { id: 'bc', label: 'Bottom Center' }, { id: 'br', label: 'Bottom Right' }
  ];

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-4 uppercase tracking-tighter">Page Numbers</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium">Add professional labels with custom styling.</p>
      </div>

      {!file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-list-ol" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in zoom-in duration-300">
           <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <div className="mb-4 flex justify-between items-center px-2">
                <span className="text-[10px] font-black uppercase text-teal-600 tracking-widest">Layout</span>
                <button onClick={() => setFile(null)} className="text-slate-400 text-[10px] font-black uppercase">Remove</button>
             </div>
             <PDFPreview file={file} className="aspect-[3/4]" />
           </div>

           <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl space-y-8">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Placement</label>
                <div className="grid grid-cols-3 gap-2">
                   {positions.map(item => (
                     <button 
                       key={item.id} 
                       onClick={() => setPos(item.id as any)}
                       className={`h-16 rounded-xl border-2 transition-all flex flex-col items-center justify-center ${pos === item.id ? 'border-teal-500 bg-teal-50 dark:bg-teal-900/20 text-teal-600' : 'border-slate-100 dark:border-slate-800 text-slate-400'}`}
                     >
                       <span className="text-[9px] font-black uppercase tracking-widest">{item.label}</span>
                     </button>
                   ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Color</label>
                    <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-12 rounded-xl cursor-pointer bg-slate-100 dark:bg-slate-950 p-1 border-0" />
                 </div>
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Size: {fontSize}pt</label>
                    <input type="range" min="6" max="24" value={fontSize} onChange={e => setFontSize(parseInt(e.target.value))} className="w-full h-12 accent-teal-500" />
                 </div>
              </div>

              <button onClick={addNumbers} className="w-full bg-slate-900 dark:bg-teal-600 text-white py-5 rounded-[2rem] font-black text-lg shadow-xl active:scale-95 transition-all">
                Generate Numbered PDF
              </button>
           </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3rem] border-2 border-slate-900 dark:border-teal-500 text-center shadow-2xl animate-in zoom-in duration-300">
           <div className="text-6xl text-teal-500 mb-8"><i className="fas fa-check-circle"></i></div>
           <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-10">Process Complete!</h2>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">Download</a>
              <button onClick={() => { setFile(null); setState({status:'idle', progress: 0}) }} className="bg-slate-100 dark:bg-slate-800 text-slate-400 px-12 py-5 rounded-2xl font-black text-xl">Start New</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default Numbering;

import React, { useState, useRef, useEffect } from 'react';
import { ProcessingState } from '../types';

declare const jscanify: any;
declare const jspdf: any;
declare const cv: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [isScannerReady, setIsScannerReady] = useState(false);
  const scanner = useRef<any>(null);

  useEffect(() => {
    let checkInterval: any;

    const initScanner = () => {
      if (typeof jscanify !== 'undefined' && typeof cv !== 'undefined' && cv.Mat) {
        try {
          scanner.current = new jscanify();
          setIsScannerReady(true);
          console.log("Scanner ready.");
          if (checkInterval) clearInterval(checkInterval);
        } catch (e) {
          console.warn("Scanner not ready yet...");
        }
      }
    };

    checkInterval = setInterval(initScanner, 1000);
    initScanner();

    return () => {
      if (checkInterval) clearInterval(checkInterval);
      stopCamera();
    };
  }, []);

  const startCamera = async () => {
    try {
      // Explicitly request permissions on button click
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        videoRef.current.play();
      }
      setState({ status: 'processing', progress: 0, message: 'Camera active' });
    } catch (err) {
      console.error(err);
      alert("Please allow camera access to scan documents.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current || !scanner.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    try {
      const resultCanvas = scanner.current.extractPaper(canvas, 1200, 1697);
      setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg', 0.9)]);
    } catch (e) {
      setCapturedImages(prev => [...prev, canvas.toDataURL('image/jpeg', 0.9)]);
    }
  };

  const generatePDF = () => {
    if (capturedImages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Saving PDF...' });

    try {
      const { jsPDF } = jspdf;
      const doc = new jsPDF('p', 'mm', 'a4');

      capturedImages.forEach((img, idx) => {
        if (idx > 0) doc.addPage();
        doc.addImage(img, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
      });

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: `scan_${Date.now()}.pdf` });
      stopCamera();
    } catch (error) {
      setState({ status: 'error', progress: 0, message: 'Save failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Document Scan</h1>
        <p className="text-slate-500 dark:text-slate-400 font-medium">Capture and digitize documents instantly.</p>

        {!isScannerReady && state.status !== 'success' && (
          <div className="mt-4 inline-flex items-center gap-2 px-6 py-2 bg-slate-100 dark:bg-slate-900 rounded-full text-[10px] font-black uppercase tracking-widest animate-pulse">
            <i className="fas fa-circle-notch fa-spin text-teal-500"></i> Initializing AI Engine...
          </div>
        )}
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-20 rounded-[3rem] border-4 border-dashed border-slate-200 dark:border-slate-800 text-center shadow-2xl flex flex-col items-center">
          <div className="w-24 h-24 bg-teal-50 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-[2rem] flex items-center justify-center text-4xl mb-8">
            <i className="fas fa-camera"></i>
          </div>
          <button 
            onClick={startCamera} 
            disabled={!isScannerReady}
            className="bg-teal-600 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl shadow-teal-500/20 active:scale-95 transition-all"
          >
            Start Scanning
          </button>
        </div>
      )}

      {stream && (
        <div className="relative rounded-[3rem] overflow-hidden bg-black aspect-[3/4] max-w-lg mx-auto ring-[12px] ring-white dark:ring-slate-900 shadow-2xl">
          <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover"></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          <div className="absolute inset-0 border-[40px] border-black/20 pointer-events-none">
             <div className="w-full h-full border-2 border-dashed border-white/50 rounded-2xl"></div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-6">
            <button onClick={captureFrame} className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-teal-600 text-2xl shadow-2xl border-4 border-teal-500/20 active:scale-90 transition-all">
              <i className="fas fa-camera"></i>
            </button>

            {capturedImages.length > 0 && (
              <button onClick={generatePDF} className="bg-teal-600 text-white px-8 py-5 rounded-2xl font-black text-sm shadow-xl flex items-center gap-3">
                Save PDF <span className="bg-white/20 px-2 py-0.5 rounded text-[10px]">{capturedImages.length}</span>
              </button>
            )}

            <button onClick={stopCamera} className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all">
               <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      {capturedImages.length > 0 && (
        <div className="mt-12 flex gap-4 overflow-x-auto pb-4 no-scrollbar px-4">
            {capturedImages.map((img, i) => (
              <div key={i} className="flex-shrink-0 w-24 aspect-[3/4] rounded-xl border-4 border-white dark:border-slate-800 overflow-hidden shadow-lg">
                <img src={img} className="w-full h-full object-cover" />
              </div>
            ))}
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3rem] border-2 border-teal-500 text-center shadow-2xl">
          <div className="w-20 h-20 bg-teal-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-4xl font-black dark:text-white mb-10">Scan Saved!</h2>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">
              Download
            </a>
            <button onClick={() => { setCapturedImages([]); setState({ status: 'idle', progress: 0 }); }} className="bg-slate-100 dark:bg-slate-800 text-slate-400 px-12 py-5 rounded-2xl font-black text-xl">
              New Scan
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import PDFPreview from '../components/PDFPreview';
import { ProcessingState } from '../types';

declare const pdfjsLib: any;
declare const jspdf: any;

const Protect: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [password, setPassword] = useState('');
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const protect = async () => {
    if (!file || !password) return;

    setState({ status: 'processing', progress: 10, message: 'Applying encryption...' });

    try {
      const { jsPDF } = jspdf;
      const arrayBuffer = await file.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      const numPages = pdf.numPages;

      // We recreate the PDF with encryption. 
      const doc = new jsPDF({
        encryption: {
          userPassword: password,
          ownerPassword: password,
          userPermissions: ['print', 'modify', 'copy', 'annotating']
        }
      });

      for (let i = 1; i <= numPages; i++) {
        setState({ 
          status: 'processing', 
          progress: Math.round((i / numPages) * 100), 
          message: `Securing page ${i}...` 
        });

        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 2.0 });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        if (!context) continue;

        canvas.height = viewport.height;
        canvas.width = viewport.width;

        await page.render({ canvasContext: context, viewport }).promise;
        const imgData = canvas.toDataURL('image/jpeg', 0.9);

        if (i > 1) doc.addPage([viewport.width, viewport.height]);
        else {
          doc.deletePage(1);
          doc.addPage([viewport.width, viewport.height]);
        }

        doc.addImage(imgData, 'JPEG', 0, 0, viewport.width, viewport.height);
      }

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ status: 'success', progress: 100, resultUrl: url, resultFileName: `locked_${file.name}` });
    } catch (error) {
      console.error('Protection Error:', error);
      setState({ status: 'error', progress: 0, message: 'Encryption failed. Check file validity.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-4 uppercase tracking-tighter">Protect PDF</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium tracking-tight">Add secure password protection locally.</p>
      </div>

      {state.status === 'idle' && !file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-lock" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <PDFPreview file={file} className="aspect-[3/4]" />
             <div className="mt-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">{file.name}</div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl flex flex-col justify-center">
             <div className="mb-8">
                <label className="block text-[10px] font-black text-teal-600 uppercase tracking-[0.2em] mb-4">Access Password</label>
                <input 
                  type="password" 
                  value={password} 
                  onChange={e => setPassword(e.target.value)}
                  className="w-full px-6 py-5 rounded-2xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950 focus:border-teal-500 outline-none text-slate-900 dark:text-white font-bold"
                  placeholder="Password required to open..."
                />
             </div>

             <button 
                onClick={protect} 
                disabled={!password || state.status === 'processing'}
                className="w-full bg-slate-900 dark:bg-teal-600 text-white py-5 rounded-2xl font-black text-lg active:scale-95 transition-all shadow-xl disabled:opacity-50"
             >
               {state.status === 'processing' ? <i className="fas fa-spinner fa-spin mr-2"></i> : 'Apply Lock'}
             </button>
             <button onClick={() => setFile(null)} className="mt-4 text-[10px] font-black text-slate-400 uppercase">Cancel</button>
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[2.5rem] border-4 border-teal-500 text-center shadow-2xl">
           <div className="w-20 h-20 bg-teal-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8">
             <i className="fas fa-lock"></i>
           </div>
           <h2 className="text-3xl font-black mb-10 dark:text-white uppercase tracking-tighter">Document Secured!</h2>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">
              Download Locked PDF
            </a>
            <button onClick={() => { setFile(null); setPassword(''); setState({status: 'idle', progress: 0})}} className="bg-slate-100 dark:bg-slate-800 text-slate-400 px-8 py-5 rounded-2xl font-black text-sm uppercase">
              Start New
            </button>
           </div>
        </div>
      )}
    </div>
  );
};

export default Protect;

