import React, { useState, useRef, useEffect } from 'react';
import { ProcessingState } from '../types';

declare const jscanify: any;
declare const jspdf: any;
declare const cv: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [isScannerReady, setIsScannerReady] = useState(false);
  const scanner = useRef<any>(null);

  // Initialize Scanner Engine
  useEffect(() => {
    let checkInterval: any;
    const initScanner = () => {
      // jscanify depends on OpenCV (cv) being ready
      if (typeof jscanify !== 'undefined' && typeof cv !== 'undefined' && cv.Mat) {
        try {
          scanner.current = new jscanify();
          setIsScannerReady(true);
          console.log("Scanner engine initialized.");
          if (checkInterval) clearInterval(checkInterval);
        } catch (e) {
          console.warn("Waiting for OpenCV runtime...");
        }
      }
    };
    checkInterval = setInterval(initScanner, 800);
    initScanner();
    return () => {
      if (checkInterval) clearInterval(checkInterval);
      stopCamera();
    };
  }, []);

  // Ensure stream is attached when video element appears
  useEffect(() => {
    if (stream && videoRef.current) {
      videoRef.current.srcObject = stream;
      // Many mobile browsers require user interaction to play video, 
      // but since this is triggered by a button click, it should work.
    }
  }, [stream]);

  const startCamera = async () => {
    try {
      // Requesting environment camera with ideal resolution
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment', 
          width: { ideal: 1920 }, 
          height: { ideal: 1080 } 
        },
        audio: false 
      });
      setStream(mediaStream);
      setState({ status: 'processing', progress: 0, message: 'Camera active' });
    } catch (err) {
      console.error("Camera Error:", err);
      alert("Could not access camera. Please ensure you have granted permissions and are using HTTPS.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
      setState({ status: 'idle', progress: 0 });
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current || !scanner.current) return;

    // Ensure video is actually playing and has dimensions
    if (videoRef.current.readyState < 2 || videoRef.current.videoWidth === 0) {
      console.warn("Video metadata not ready");
      return;
    }

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    try {
      // jscanify extracts the paper from the frame
      // A4 ratio is roughly 1:1.414
      const resultCanvas = scanner.current.extractPaper(canvas, 1200, 1697);
      setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg', 0.85)]);
    } catch (e) {
      console.error("Extraction failed, using raw frame", e);
      setCapturedImages(prev => [...prev, canvas.toDataURL('image/jpeg', 0.85)]);
    }
  };

  const generatePDF = () => {
    if (capturedImages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Compiling PDF...' });

    try {
      const { jsPDF } = jspdf;
      // Create A4 PDF
      const doc = new jsPDF('p', 'mm', 'a4');

      capturedImages.forEach((img, idx) => {
        if (idx > 0) doc.addPage();
        // A4 dimensions: 210 x 297 mm
        doc.addImage(img, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
      });

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `scan_${new Date().getTime()}.pdf` 
      });
      stopCamera();
    } catch (error) {
      console.error("PDF Generation Error:", error);
      setState({ status: 'error', progress: 0, message: 'Save failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 transition-colors duration-300">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Document Scan</h1>
        <p className="text-slate-500 dark:text-slate-400 font-medium">Capture and digitize paper documents instantly.</p>

        {!isScannerReady && state.status !== 'success' && (
          <div className="mt-6 inline-flex items-center gap-3 px-6 py-2 bg-slate-100 dark:bg-slate-900 rounded-full text-[10px] font-black uppercase tracking-widest text-teal-600 animate-pulse border border-teal-500/20">
            <i className="fas fa-circle-notch fa-spin"></i> Initializing Scanning Engine...
          </div>
        )}
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-20 rounded-[3rem] border-4 border-dashed border-slate-100 dark:border-slate-800 text-center shadow-2xl flex flex-col items-center">
          <div className="w-24 h-24 bg-teal-50 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-[2rem] flex items-center justify-center text-4xl mb-8 shadow-inner">
            <i className="fas fa-camera"></i>
          </div>
          <button 
            onClick={startCamera} 
            disabled={!isScannerReady}
            className="bg-teal-600 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl shadow-teal-500/20 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-wait"
          >
            Start Scanning
          </button>
          <p className="mt-6 text-[10px] font-black uppercase text-slate-400 tracking-widest">Supports mobile environment cameras</p>
        </div>
      )}

      {stream && (
        <div className="relative rounded-[3rem] overflow-hidden bg-black aspect-[3/4] max-w-lg mx-auto ring-[12px] ring-white dark:ring-slate-900 shadow-2xl animate-in fade-in zoom-in duration-500">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="w-full h-full object-cover"
          ></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          {/* Viewfinder Overlay */}
          <div className="absolute inset-0 border-[60px] border-black/30 pointer-events-none">
             <div className="w-full h-full border-2 border-dashed border-white/40 rounded-2xl flex items-center justify-center">
                <div className="w-8 h-8 border-t-2 border-l-2 border-white/60 absolute top-4 left-4"></div>
                <div className="w-8 h-8 border-t-2 border-r-2 border-white/60 absolute top-4 right-4"></div>
                <div className="w-8 h-8 border-b-2 border-l-2 border-white/60 absolute bottom-4 left-4"></div>
                <div className="w-8 h-8 border-b-2 border-r-2 border-white/60 absolute bottom-4 right-4"></div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-6 z-10 px-6">
            <button 
              onClick={captureFrame} 
              className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-teal-600 text-3xl shadow-2xl border-4 border-teal-500/20 active:scale-90 transition-all hover:bg-teal-50"
              title="Capture Page"
            >
              <i className="fas fa-circle"></i>
            </button>

            {capturedImages.length > 0 && (
              <button 
                onClick={generatePDF} 
                className="bg-teal-600 text-white px-8 py-5 rounded-2xl font-black text-sm shadow-xl flex items-center gap-3 active:scale-95"
              >
                Finish <span className="bg-white/20 px-2 py-0.5 rounded text-[10px]">{capturedImages.length}</span>
              </button>
            )}

            <button 
              onClick={stopCamera} 
              className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all"
              title="Close Camera"
            >
               <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      {capturedImages.length > 0 && (
        <div className="mt-12">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center mb-6">Captured Pages ({capturedImages.length})</h3>
          <div className="flex gap-4 overflow-x-auto pb-6 no-scrollbar px-4">
              {capturedImages.map((img, i) => (
                <div key={i} className="flex-shrink-0 w-28 aspect-[3/4] rounded-2xl border-4 border-white dark:border-slate-800 overflow-hidden shadow-xl relative group">
                  <img src={img} className="w-full h-full object-cover" alt={`Scan ${i + 1}`} />
                  <button 
                    onClick={() => setCapturedImages(prev => prev.filter((_, idx) => idx !== i))}
                    className="absolute inset-0 bg-rose-500/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <i className="fas fa-trash text-lg"></i>
                  </button>
                  <div className="absolute top-2 left-2 bg-black/40 text-white text-[8px] font-black px-1.5 py-0.5 rounded-md backdrop-blur-sm">
                    #{i + 1}
                  </div>
                </div>
              ))}
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] border-2 border-teal-500 text-center shadow-2xl animate-in zoom-in duration-500">
          <div className="w-20 h-20 bg-teal-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-teal-500/20">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-4xl font-[900] text-slate-900 dark:text-white mb-4 tracking-tighter uppercase">Scan Complete!</h2>
          <p className="text-slate-500 dark:text-slate-400 font-medium mb-10">Your multipage document has been converted to a high-quality PDF.</p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
              <i className="fas fa-download"></i> Download PDF
            </a>
            <button 
              onClick={() => { setCapturedImages([]); setState({ status: 'idle', progress: 0 }); }} 
              className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-12 py-5 rounded-2xl font-black text-sm uppercase active:scale-95"
            >
              New Scan
            </button>
          </div>
        </div>
      )}

      {state.status === 'error' && (
        <div className="mt-8 p-6 bg-rose-50 dark:bg-rose-950/20 border border-rose-200 dark:border-rose-900 rounded-3xl text-rose-600 dark:text-rose-400 font-black text-center text-sm uppercase tracking-widest">
          <i className="fas fa-exclamation-triangle mr-2"></i> {state.message}
        </div>
      )}
    </div>
  );
};

