                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${wmType === 'image' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                >
                  Logo Branding
                </button>
              </div>

              {/* Advanced Controls Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  {wmType === 'text' ? (
