import React, { useState, useRef, useEffect } from 'react';
import { ProcessingState } from '../types';

declare const jscanify: any;
declare const jspdf: any;
declare const cv: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [isScannerReady, setIsScannerReady] = useState(false);
  const scanner = useRef<any>(null);

  // Initialize Scanner Engine - Listen for OpenCV Ready
  useEffect(() => {
    const initScanner = () => {
      if (typeof jscanify !== 'undefined' && typeof cv !== 'undefined' && cv.Mat) {
        try {
          scanner.current = new jscanify();
          setIsScannerReady(true);
          console.log("Scanner engine initialized successfully.");
        } catch (e) {
          console.error("Scanner init error:", e);
        }
      }
    };

    // If OpenCV is already loaded
    if (typeof cv !== 'undefined' && cv.Mat) {
      initScanner();
    } else {
      // Listen for the custom event from index.html
      window.addEventListener('opencv-ready', initScanner);
    }

    return () => {
      window.removeEventListener('opencv-ready', initScanner);
      stopCamera();
    };
  }, []);

  const startCamera = async () => {
    try {
      // Relaxed constraints for better mobile success
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: { ideal: 'environment' },
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false 
      });

      setStream(mediaStream);

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        // Wait for metadata to ensure video has dimensions before playing
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Play error:", e));
        };
      }

      setState({ status: 'processing', progress: 0, message: 'Camera active' });
    } catch (err) {
      console.error("Camera access failed:", err);
      alert("Unable to open camera. Please check permissions and ensure you're on HTTPS.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current || !scanner.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    try {
      // Attempt paper extraction
      const resultCanvas = scanner.current.extractPaper(canvas, 1200, 1697);
      setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg', 0.85)]);
    } catch (e) {
      console.warn("Paper extraction failed, using raw frame instead.");
      setCapturedImages(prev => [...prev, canvas.toDataURL('image/jpeg', 0.85)]);
    }
  };

  const generatePDF = () => {
    if (capturedImages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Creating Document...' });

    try {
      const { jsPDF } = jspdf;
      const doc = new jsPDF('p', 'mm', 'a4');

      capturedImages.forEach((img, idx) => {
        if (idx > 0) doc.addPage();
        doc.addImage(img, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
      });

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `scan_${Date.now()}.pdf` 
      });
      stopCamera();
    } catch (error) {
      setState({ status: 'error', progress: 0, message: 'Save failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Document Scan</h1>
        <p className="text-slate-500 dark:text-slate-400 font-medium">Capture paper documents instantly.</p>

        {!isScannerReady && (
          <div className="mt-8 bg-slate-100 dark:bg-slate-900 px-6 py-3 rounded-full inline-flex items-center gap-3 border border-teal-500/20">
            <i className="fas fa-circle-notch fa-spin text-teal-600"></i>
            <span className="text-[10px] font-black uppercase tracking-widest text-teal-600 dark:text-teal-400">INITIALIZING SCANNING ENGINE...</span>
          </div>
        )}
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-20 rounded-[3rem] border-4 border-dashed border-slate-100 dark:border-slate-800 text-center shadow-2xl flex flex-col items-center">
          <div className="w-24 h-24 bg-teal-50 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-[2rem] flex items-center justify-center text-4xl mb-8">
            <i className="fas fa-camera"></i>
          </div>
          <button 
            onClick={startCamera} 
            disabled={!isScannerReady}
            className="bg-teal-600 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl shadow-teal-500/20 active:scale-95 transition-all disabled:opacity-50"
          >
            Start Scanning
          </button>
          <p className="mt-6 text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">Uses back camera by default</p>
        </div>
      )}

      {stream && (
        <div className="relative rounded-[3rem] overflow-hidden bg-black aspect-[3/4] max-w-lg mx-auto ring-[12px] ring-white dark:ring-slate-900 shadow-2xl">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="w-full h-full object-cover"
          ></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          <div className="absolute inset-0 border-[40px] border-black/20 pointer-events-none">
             <div className="w-full h-full border-2 border-dashed border-white/50 rounded-2xl"></div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-6 z-10">
            <button 
              onClick={captureFrame} 
              className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-teal-600 text-3xl shadow-2xl border-4 border-teal-500/20 active:scale-90 transition-all"
            >
              <i className="fas fa-circle"></i>
            </button>
            {capturedImages.length > 0 && (
              <button onClick={generatePDF} className="bg-teal-600 text-white px-8 py-5 rounded-2xl font-black text-sm shadow-xl flex items-center gap-3">
                Finish <span className="bg-white/20 px-2 py-0.5 rounded text-[10px]">{capturedImages.length}</span>
              </button>
            )}
            <button onClick={stopCamera} className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-lg">
               <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      {capturedImages.length > 0 && (
        <div className="mt-12 flex gap-4 overflow-x-auto pb-4 no-scrollbar px-4">
            {capturedImages.map((img, i) => (
              <div key={i} className="flex-shrink-0 w-24 aspect-[3/4] rounded-2xl border-4 border-white dark:border-slate-800 overflow-hidden shadow-lg relative group">
                <img src={img} className="w-full h-full object-cover" />
                <button 
                  onClick={() => setCapturedImages(prev => prev.filter((_, idx) => idx !== i))}
                  className="absolute inset-0 bg-rose-500/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <i className="fas fa-trash text-sm"></i>
                </button>
              </div>
            ))}
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] border-2 border-teal-500 text-center shadow-2xl">
          <div className="w-20 h-20 bg-teal-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-teal-500/20">
            <i className="fas fa-check"></i>
          </div>
          <h2 className="text-4xl font-[900] text-slate-900 dark:text-white mb-10 tracking-tighter uppercase">Scan Complete!</h2>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl active:scale-95 transition-all">
              Download PDF
            </a>
            <button onClick={() => { setCapturedImages([]); setState({ status: 'idle', progress: 0 }); }} className="bg-slate-100 dark:bg-slate-800 text-slate-500 px-12 py-5 rounded-2xl font-black text-sm uppercase">
              Start New
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import PDFPreview from '../components/PDFPreview';
import { ProcessingState } from '../types';

type Alignment = 'TL' | 'TC' | 'TR' | 'ML' | 'MC' | 'MR' | 'BL' | 'BC' | 'BR';

const Watermark: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [wmType, setWmType] = useState<'text' | 'image'>('text');
  const [text, setText] = useState('CONFIDENTIAL');
  const [logo, setLogo] = useState<File | null>(null);
  const [opacity, setOpacity] = useState(0.4);
  const [rotation, setRotation] = useState(45);
  const [scale, setScale] = useState(1.0);
  const [color, setColor] = useState('#64748b');
  const [alignment, setAlignment] = useState<Alignment>('MC');
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const apply = async () => {
    if (!file) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) return;

    setState({ status: 'processing', progress: 30, message: 'Branding PDF...' });

    try {
      const { rgb, degrees, StandardFonts } = PDFLib;
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const pages = pdfDoc.getPages();

      const hexToRgb = (hex: string) => {
        const r = parseInt(hex.slice(1, 3), 16) / 255;
        const g = parseInt(hex.slice(3, 5), 16) / 255;
        const b = parseInt(hex.slice(5, 7), 16) / 255;
        return rgb(r, g, b);
      };

      let embeddedImage: any = null;
      if (wmType === 'image' && logo) {
        const logoBytes = await logo.arrayBuffer();
        embeddedImage = logo.type === 'image/png' 
          ? await pdfDoc.embedPng(logoBytes) 
          : await pdfDoc.embedJpg(logoBytes);
      }

      const helveticaFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      pages.forEach((page: any) => {
        const { width, height } = page.getSize();

        const calculatePosition = (wmWidth: number, wmHeight: number) => {
          let px = width / 2 - wmWidth / 2;
          let py = height / 2 - wmHeight / 2;

          if (alignment.startsWith('T')) py = height - wmHeight - 50;
          if (alignment.startsWith('B')) py = 50;
          if (alignment.endsWith('L')) px = 50;
          if (alignment.endsWith('R')) px = width - wmWidth - 50;

          return { px, py };
        };

        if (wmType === 'text') {
          const fontSize = 50 * scale;
          const textWidth = helveticaFont.widthOfTextAtSize(text, fontSize);
          const { px, py } = calculatePosition(textWidth, fontSize);

          page.drawText(text, {
            x: px,
            y: py,
            size: fontSize,
            font: helveticaFont,
            color: hexToRgb(color),
            rotate: degrees(rotation),
            opacity: opacity,
          });
        } else if (embeddedImage) {
          const imgDims = embeddedImage.scale(0.3 * scale);
          const { px, py } = calculatePosition(imgDims.width, imgDims.height);

          page.drawImage(embeddedImage, {
            x: px,
            y: py,
            width: imgDims.width,
            height: imgDims.height,
            rotate: degrees(rotation),
            opacity: opacity,
          });
        }
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: URL.createObjectURL(blob), 
        resultFileName: `marked_${file.name}` 
      });
    } catch (err) {
      console.error(err);
      setState({ status: 'error', progress: 0, message: 'Watermark failed. Try a smaller logo.' });
    }
  };

  const alignOptions: Alignment[] = ['TL', 'TC', 'TR', 'ML', 'MC', 'MR', 'BL', 'BC', 'BR'];

  return (
    <div className="max-w-5xl mx-auto px-4 py-12 transition-colors duration-300">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-4 uppercase tracking-tighter">Watermark Pro</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium tracking-tight">Add secure text stamps or brand logos locally.</p>
      </div>

      {!file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-stamp" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in zoom-in duration-500">

          <div className="lg:col-span-5 bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <div className="flex justify-between items-center mb-6 px-2">
                <span className="text-[10px] font-black uppercase tracking-widest text-teal-600 dark:text-teal-400">Document View</span>
                <button onClick={() => setFile(null)} className="text-slate-400 hover:text-rose-500 text-[10px] font-black uppercase">Change</button>
             </div>
             <PDFPreview file={file} className="aspect-[3/4] shadow-inner" />
          </div>

          <div className="lg:col-span-7 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl space-y-8">

              <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl">
                <button 
                  onClick={() => setWmType('text')} 
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${wmType === 'text' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-sm' : 'text-slate-500'}`}
                >
                  Text Stamp
                </button>
                <button 
                  onClick={() => setWmType('image')} 
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${wmType === 'image' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-sm' : 'text-slate-500'}`}
                >
                  Logo Upload
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  {wmType === 'text' ? (
                    <div>
                      <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3">Stamp Content</label>
                      <input 
                        type="text" 
                        value={text} 
                        onChange={e => setText(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 p-5 rounded-2xl border-2 border-slate-100 dark:border-slate-700 outline-none focus:border-teal-500 font-bold dark:text-white" 
                      />
                    </div>
                  ) : (
                    <div>
                      <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3">Branding Logo</label>
                      <input 
                        type="file" 
                        accept="image/*" 
                        onChange={e => setLogo(e.target.files?.[0] || null)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-2 border-slate-100 dark:border-slate-700 text-[10px] dark:text-slate-400" 
                      />
                    </div>
                  )}

                  <div>
                    <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3">Positioning</label>
                    <div className="grid grid-cols-3 gap-2 max-w-[150px]">
                        {alignOptions.map(opt => (
                          <button 
                            key={opt}
                            onClick={() => setAlignment(opt)}
                            className={`w-10 h-10 rounded-xl border-2 flex items-center justify-center transition-all ${alignment === opt ? 'bg-teal-500 border-teal-600 shadow-lg shadow-teal-500/20' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700'}`}
                          >
                             <div className={`w-1.5 h-1.5 rounded-full ${alignment === opt ? 'bg-white' : 'bg-slate-300 dark:bg-slate-600'}`}></div>
                          </button>
                        ))}
                    </div>
                  </div>
                </div>

                <div className="space-y-6">
                  {wmType === 'text' && (
                    <div>
                      <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3">Text Color</label>
                      <div className="flex items-center gap-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl border-2 border-slate-100 dark:border-slate-700">
                        <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-12 h-12 rounded-xl cursor-pointer border-0 bg-transparent" />
                        <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{color}</span>
                      </div>
                    </div>
                  )}

                  <div className="space-y-4">
                    <div className="flex justify-between">
                       <span className="text-[10px] font-black uppercase text-teal-600 dark:text-teal-400 tracking-widest">Opacity: {Math.round(opacity * 100)}%</span>
                    </div>
                    <input type="range" min="0.1" max="1" step="0.1" value={opacity} onChange={e => setOpacity(parseFloat(e.target.value))} className="w-full h-2 rounded-lg accent-teal-500" />
                  </div>

                  <div className="space-y-4">
                    <div className="flex justify-between">
                       <span className="text-[10px] font-black uppercase text-teal-600 dark:text-teal-400 tracking-widest">Scale: {scale}x</span>
                    </div>
                    <input type="range" min="0.5" max="3" step="0.1" value={scale} onChange={e => setScale(parseFloat(e.target.value))} className="w-full h-2 rounded-lg accent-teal-500" />
                  </div>
                </div>
              </div>

              <button 
                onClick={apply} 
                disabled={state.status === 'processing' || (wmType === 'image' && !logo)}
                className="w-full bg-slate-900 dark:bg-teal-600 text-white py-5 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all disabled:opacity-30"
              >
                {state.status === 'processing' ? <i className="fas fa-spinner fa-spin mr-3"></i> : 'Apply to Document'}
              </button>
            </div>
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-16 rounded-[4rem] border-4 border-teal-500 text-center shadow-2xl max-w-2xl mx-auto">
           <div className="w-20 h-20 bg-teal-500 text-white text-3xl rounded-full flex items-center justify-center mx-auto mb-10">
             <i className="fas fa-check-double"></i>
           </div>
           <h2 className="text-4xl font-[900] text-slate-900 dark:text-white mb-6 uppercase tracking-tighter">PDF Branded!</h2>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-3xl font-black text-xl shadow-xl active:scale-95 transition-all">
                Download PDF
              </a>
              <button onClick={() => { setFile(null); setLogo(null); setState({status:'idle', progress: 0}) }} className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-10 py-5 rounded-3xl font-black text-sm uppercase">
                New Task
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

export default Watermark;

import React, { useState, useRef, useEffect } from 'react';
import { ProcessingState } from '../types';

declare const jscanify: any;
declare const jspdf: any;
declare const cv: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [isScannerReady, setIsScannerReady] = useState(false);
  const scanner = useRef<any>(null);

  // Initialize Scanner Engine - Poll until OpenCV is actually operational
  useEffect(() => {
    let pollInterval: any;

    const tryInit = () => {
      if (typeof jscanify !== 'undefined' && typeof cv !== 'undefined' && cv.Mat) {
        try {
          // Extra check: try creating a matrix to ensure WASM is ready
          const test = new cv.Mat();
          test.delete();

          scanner.current = new jscanify();
          setIsScannerReady(true);
          console.log("Scanner engine is operational.");
          if (pollInterval) clearInterval(pollInterval);
        } catch (e) {
          console.log("Waiting for OpenCV WASM runtime...");
        }
      }
    };

    pollInterval = setInterval(tryInit, 500);
    tryInit();

    return () => {
      if (pollInterval) clearInterval(pollInterval);
      stopCamera();
    };
  }, []);

  const startCamera = async () => {
    try {
      // Step 1: Request permissions with basic constraints first
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: { ideal: 'environment' }
        },
        audio: false 
      });

      setStream(mediaStream);

      // Step 2: Attach to video element
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => {
            console.error("Autoplay prevented:", e);
            alert("Please tap to start the camera view.");
          });
        };
      }

      setState({ status: 'processing', progress: 0, message: 'Camera active' });
    } catch (err) {
      console.error("Camera access failed:", err);
      alert("Camera error. Please ensure you have given permission and are using a secure (HTTPS) connection.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current || !scanner.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    try {
      // Paper extraction attempt
      const resultCanvas = scanner.current.extractPaper(canvas, 1200, 1697);
      setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg', 0.85)]);
    } catch (e) {
      console.warn("Auto-crop failed, capturing raw frame.");
      setCapturedImages(prev => [...prev, canvas.toDataURL('image/jpeg', 0.85)]);
    }
  };

  const generatePDF = () => {
    if (capturedImages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Compiling PDF...' });

    try {
      const { jsPDF } = jspdf;
      const doc = new jsPDF('p', 'mm', 'a4');

      capturedImages.forEach((img, idx) => {
        if (idx > 0) doc.addPage();
        doc.addImage(img, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
      });

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `scan_${Date.now()}.pdf` 
      });
      stopCamera();
    } catch (error) {
      setState({ status: 'error', progress: 0, message: 'PDF creation failed.' });
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 transition-colors duration-300">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Document Scan</h1>
        <p className="text-slate-500 dark:text-slate-400 font-medium">Capture and digitize paper documents instantly.</p>

        {!isScannerReady && (
          <div className="mt-8 bg-teal-50 dark:bg-teal-900/20 px-6 py-3 rounded-full inline-flex items-center gap-3 border border-teal-500/20 animate-pulse">
            <i className="fas fa-circle-notch fa-spin text-teal-600"></i>
            <span className="text-[10px] font-black uppercase tracking-widest text-teal-600 dark:text-teal-400">Scanner Engine Warming Up...</span>
          </div>
        )}
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-20 rounded-[3rem] border-4 border-dashed border-slate-100 dark:border-slate-800 text-center shadow-2xl flex flex-col items-center">
          <div className="w-24 h-24 bg-teal-50 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-[2.5rem] flex items-center justify-center text-4xl mb-8 shadow-inner">
            <i className="fas fa-camera"></i>
          </div>
          <button 
            onClick={startCamera} 
            disabled={!isScannerReady}
            className="bg-teal-600 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-xl shadow-teal-500/20 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-wait"
          >
            Start Camera
          </button>
          <p className="mt-6 text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">Supports multiple pages</p>
        </div>
      )}

      {stream && (
        <div className="relative rounded-[3rem] overflow-hidden bg-black aspect-[3/4] max-w-lg mx-auto ring-[12px] ring-white dark:ring-slate-900 shadow-2xl animate-in zoom-in duration-500">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="w-full h-full object-cover"
          ></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          <div className="absolute inset-0 border-[60px] border-black/30 pointer-events-none">
             <div className="w-full h-full border-2 border-dashed border-white/40 rounded-2xl flex items-center justify-center">
                <i className="fas fa-expand text-white/20 text-6xl"></i>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-6 z-10 px-6">
            <button 
              onClick={captureFrame} 
              className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-teal-600 text-3xl shadow-2xl border-4 border-teal-500/20 active:scale-90 transition-all hover:bg-teal-50"
            >
              <i className="fas fa-circle"></i>
            </button>
            {capturedImages.length > 0 && (
              <button onClick={generatePDF} className="bg-teal-600 text-white px-8 py-5 rounded-2xl font-black text-sm shadow-xl flex items-center gap-3 active:scale-95">
                Save <span className="bg-white/20 px-2 py-0.5 rounded text-[10px]">{capturedImages.length}</span>
              </button>
            )}
            <button onClick={stopCamera} className="w-12 h-12 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90">
               <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      {capturedImages.length > 0 && (
        <div className="mt-12">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center mb-6">Gallery ({capturedImages.length})</h3>
          <div className="flex gap-4 overflow-x-auto pb-6 no-scrollbar px-4">
              {capturedImages.map((img, i) => (
                <div key={i} className="flex-shrink-0 w-28 aspect-[3/4] rounded-2xl border-4 border-white dark:border-slate-800 overflow-hidden shadow-xl relative group">
                  <img src={img} className="w-full h-full object-cover" alt={`Page ${i+1}`} />
                  <button 
                    onClick={() => setCapturedImages(prev => prev.filter((_, idx) => idx !== i))}
                    className="absolute inset-0 bg-rose-500/60 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <i className="fas fa-trash text-lg"></i>
                  </button>
                  <div className="absolute top-2 left-2 bg-black/50 text-white text-[8px] font-black px-1.5 py-0.5 rounded">#{i+1}</div>
                </div>
              ))}
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-12 rounded-[4rem] border-4 border-teal-500 text-center shadow-2xl animate-in zoom-in duration-500">
          <div className="w-24 h-24 bg-teal-500 text-white text-4xl rounded-full flex items-center justify-center mx-auto mb-10 shadow-xl shadow-teal-500/30">
            <i className="fas fa-check-double"></i>
          </div>
          <h2 className="text-4xl font-[900] text-slate-900 dark:text-white mb-6 tracking-tighter uppercase">Success!</h2>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-3xl font-black text-xl shadow-xl active:scale-95 transition-all">
              Download PDF
            </a>
            <button onClick={() => { setCapturedImages([]); setState({ status: 'idle', progress: 0 }); }} className="bg-slate-100 dark:bg-slate-800 text-slate-500 px-12 py-5 rounded-3xl font-black text-sm uppercase">
              New Scan
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState } from 'react';
import Dropzone from '../components/Dropzone';
import PDFPreview from '../components/PDFPreview';
import { ProcessingState } from '../types';

type Alignment = 'TL' | 'TC' | 'TR' | 'ML' | 'MC' | 'MR' | 'BL' | 'BC' | 'BR';

const Watermark: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [wmType, setWmType] = useState<'text' | 'image'>('text');
  const [text, setText] = useState('CONFIDENTIAL');
  const [logo, setLogo] = useState<File | null>(null);
  const [opacity, setOpacity] = useState(0.4);
  const [rotation, setRotation] = useState(45);
  const [scale, setScale] = useState(1.0);
  const [color, setColor] = useState('#64748b');
  const [alignment, setAlignment] = useState<Alignment>('MC');
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const apply = async () => {
    if (!file) return;
    const PDFLib = (window as any).PDFLib;
    if (!PDFLib) return;

    setState({ status: 'processing', progress: 30, message: 'Processing document...' });

    try {
      const { rgb, degrees, StandardFonts } = PDFLib;
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFLib.PDFDocument.load(bytes);
      const pages = pdfDoc.getPages();

      const hexToRgb = (hex: string) => {
        const r = parseInt(hex.slice(1, 3), 16) / 255;
        const g = parseInt(hex.slice(3, 5), 16) / 255;
        const b = parseInt(hex.slice(5, 7), 16) / 255;
        return rgb(r, g, b);
      };

      let embeddedImage: any = null;
      if (wmType === 'image' && logo) {
        const logoBytes = await logo.arrayBuffer();
        embeddedImage = logo.type === 'image/png' 
          ? await pdfDoc.embedPng(logoBytes) 
          : await pdfDoc.embedJpg(logoBytes);
      }

      const helveticaFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      pages.forEach((page: any) => {
        const { width, height } = page.getSize();

        const calculatePosition = (wmWidth: number, wmHeight: number) => {
          let px = width / 2 - wmWidth / 2;
          let py = height / 2 - wmHeight / 2;

          if (alignment.startsWith('T')) py = height - wmHeight - 50;
          if (alignment.startsWith('B')) py = 50;
          if (alignment.endsWith('L')) px = 50;
          if (alignment.endsWith('R')) px = width - wmWidth - 50;

          return { px, py };
        };

        if (wmType === 'text') {
          const fontSize = 50 * scale;
          const textWidth = helveticaFont.widthOfTextAtSize(text, fontSize);
          const { px, py } = calculatePosition(textWidth, fontSize);

          page.drawText(text, {
            x: px,
            y: py,
            size: fontSize,
            font: helveticaFont,
            color: hexToRgb(color),
            rotate: degrees(rotation),
            opacity: opacity,
          });
        } else if (embeddedImage) {
          const imgDims = embeddedImage.scale(0.3 * scale);
          const { px, py } = calculatePosition(imgDims.width, imgDims.height);

          page.drawImage(embeddedImage, {
            x: px,
            y: py,
            width: imgDims.width,
            height: imgDims.height,
            rotate: degrees(rotation),
            opacity: opacity,
          });
        }
      });

      const pdfBytes = await pdfDoc.save();
      const blob = new Blob([pdfBytes], { type: 'application/pdf' });
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: URL.createObjectURL(blob), 
        resultFileName: `marked_${file.name}` 
      });
    } catch (err) {
      console.error(err);
      setState({ status: 'error', progress: 0, message: 'Watermark application failed.' });
    }
  };

  const alignOptions: Alignment[] = ['TL', 'TC', 'TR', 'ML', 'MC', 'MR', 'BL', 'BC', 'BR'];

  return (
    <div className="max-w-5xl mx-auto px-4 py-12 transition-colors duration-300">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-4 uppercase tracking-tighter">Watermark Pro</h1>
        <p className="text-slate-600 dark:text-slate-400 font-medium tracking-tight">Secure your documents with branding or text stamps.</p>
      </div>

      {!file && <Dropzone onFilesSelected={(f) => setFile(f[0])} icon="fa-stamp" />}

      {file && state.status !== 'success' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start animate-in fade-in zoom-in duration-500">

          <div className="lg:col-span-5 bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl">
             <div className="flex justify-between items-center mb-6 px-2">
                <span className="text-[10px] font-black uppercase tracking-widest text-teal-600 dark:text-teal-400">PDF Preview</span>
                <button onClick={() => setFile(null)} className="text-slate-400 hover:text-rose-500 text-[10px] font-black uppercase transition-colors">Change File</button>
             </div>
             <PDFPreview file={file} className="aspect-[3/4] shadow-inner" />
          </div>

          <div className="lg:col-span-7 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-xl space-y-8">

              <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl">
                <button 
                  onClick={() => setWmType('text')} 
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${wmType === 'text' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                >
                  Text Stamp
                </button>
                <button 
                  onClick={() => setWmType('image')} 
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${wmType === 'image' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                >
                  Branding Logo
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  {wmType === 'text' ? (
                    <div>
                      <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3 px-1">Stamp Text</label>
                      <input 
                        type="text" 
                        value={text} 
                        onChange={e => setText(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 p-5 rounded-2xl border-2 border-slate-100 dark:border-slate-700 outline-none focus:border-teal-500 font-bold text-slate-900 dark:text-white transition-all" 
                      />
                    </div>
                  ) : (
                    <div>
                      <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3 px-1">Upload Logo</label>
                      <input 
                        type="file" 
                        accept="image/*" 
                        onChange={e => setLogo(e.target.files?.[0] || null)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-2 border-slate-100 dark:border-slate-700 text-[10px] text-slate-400 uppercase font-black" 
                      />
                    </div>
                  )}

                  <div>
                    <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3 px-1">Alignment</label>
                    <div className="grid grid-cols-3 gap-3 max-w-[150px]">
                        {alignOptions.map(opt => (
                          <button 
                            key={opt}
                            onClick={() => setAlignment(opt)}
                            className={`w-10 h-10 rounded-xl border-2 flex items-center justify-center transition-all ${alignment === opt ? 'bg-teal-500 border-teal-600 shadow-lg shadow-teal-500/20' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-teal-400'}`}
                          >
                             <div className={`w-2 h-2 rounded-full ${alignment === opt ? 'bg-white' : 'bg-slate-300 dark:bg-slate-600'}`}></div>
                          </button>
                        ))}
                    </div>
                  </div>
                </div>

                <div className="space-y-6">
                  {wmType === 'text' && (
                    <div>
                      <label className="block text-[10px] font-black text-teal-600 dark:text-teal-400 uppercase tracking-widest mb-3 px-1">Text Color</label>
                      <div className="flex items-center gap-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl border-2 border-slate-100 dark:border-slate-700">
                        <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-12 h-12 rounded-xl cursor-pointer border-0 bg-transparent" />
                        <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">{color}</span>
                      </div>
                    </div>
                  )}

                  <div className="space-y-4">
                    <div className="flex justify-between px-1">
                       <span className="text-[10px] font-black uppercase text-teal-600 dark:text-teal-400 tracking-widest">Opacity</span>
                       <span className="text-[10px] font-black text-slate-900 dark:text-white">{Math.round(opacity * 100)}%</span>
                    </div>
                    <input type="range" min="0.1" max="1" step="0.1" value={opacity} onChange={e => setOpacity(parseFloat(e.target.value))} className="w-full h-2 rounded-lg appearance-none bg-slate-100 dark:bg-slate-800 accent-teal-500" />
                  </div>

                  <div className="space-y-4">
                    <div className="flex justify-between px-1">
                       <span className="text-[10px] font-black uppercase text-teal-600 dark:text-teal-400 tracking-widest">Scale</span>
                       <span className="text-[10px] font-black text-slate-900 dark:text-white">{scale.toFixed(1)}x</span>
                    </div>
                    <input type="range" min="0.5" max="3" step="0.1" value={scale} onChange={e => setScale(parseFloat(e.target.value))} className="w-full h-2 rounded-lg appearance-none bg-slate-100 dark:bg-slate-800 accent-teal-500" />
                  </div>
                </div>
              </div>

              <button 
                onClick={apply} 
                disabled={state.status === 'processing' || (wmType === 'image' && !logo)}
                className="w-full bg-slate-900 dark:bg-teal-600 text-white py-5 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all disabled:opacity-30 disabled:cursor-not-allowed mt-4"
              >
                {state.status === 'processing' ? <i className="fas fa-spinner fa-spin mr-3"></i> : 'Apply to All Pages'}
              </button>
            </div>
          </div>
        </div>
      )}

      {state.status === 'success' && (
        <div className="bg-white dark:bg-slate-900 p-16 rounded-[4rem] border-4 border-teal-500 text-center shadow-2xl max-w-2xl mx-auto animate-in zoom-in duration-500">
           <div className="w-24 h-24 bg-teal-500 text-white text-4xl rounded-full flex items-center justify-center mx-auto mb-10 shadow-xl shadow-teal-500/30">
             <i className="fas fa-check-double"></i>
           </div>
           <h2 className="text-4xl font-[900] text-slate-900 dark:text-white mb-6 uppercase tracking-tighter">Branding Done!</h2>
           <p className="text-slate-500 dark:text-slate-400 mb-10 font-medium tracking-tight">Your watermarked PDF is secured and ready for download.</p>
           <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white px-12 py-5 rounded-3xl font-black text-xl shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                <i className="fas fa-download"></i> Download PDF
              </a>
              <button onClick={() => { setFile(null); setLogo(null); setState({status:'idle', progress: 0}) }} className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 px-10 py-5 rounded-3xl font-black text-sm uppercase active:scale-95 transition-all">
                New Task
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

export default Watermark;

import React, { useState, useRef, useEffect } from 'react';
import { ProcessingState } from '../types';

declare const jscanify: any;
declare const jspdf: any;
declare const cv: any;

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImages, setCapturedImages] = useState<string[]>([]);
  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });
  const [isScannerReady, setIsScannerReady] = useState(false);
  const scanner = useRef<any>(null);

  // Initialize Scanner - Robust Check
  useEffect(() => {
    const checkReady = () => {
      if (typeof jscanify !== 'undefined' && typeof cv !== 'undefined' && cv.Mat) {
        try {
          // Dummy matrix to confirm WASM is active
          const m = new cv.Mat();
          m.delete();
          scanner.current = new jscanify();
          setIsScannerReady(true);
          console.log("Scanner Engine Ready");
          return true;
        } catch (e) {
          return false;
        }
      }
      return false;
    };

    if (!checkReady()) {
      const interval = setInterval(() => {
        if (checkReady()) clearInterval(interval);
      }, 1000);
      return () => clearInterval(interval);
    }
  }, []);

  const startCamera = async () => {
    try {
      setState({ status: 'loading', progress: 10, message: 'Requesting Camera...' });

      const constraints = {
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        // Important: Wait for play to confirm it's actually streaming
        await videoRef.current.play();
      }

      setState({ status: 'processing', progress: 0, message: 'Camera active' });
    } catch (err) {
      console.error("Camera error:", err);
      alert("Please ensure you have granted camera permissions and are using HTTPS.");
      setState({ status: 'idle', progress: 0 });
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setState({ status: 'idle', progress: 0 });
  };

  const captureFrame = () => {
    if (!videoRef.current || !canvasRef.current || !scanner.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    ctx.drawImage(videoRef.current, 0, 0);

    try {
      // Auto-extract paper using jscanify
      const resultCanvas = scanner.current.extractPaper(canvas, 1200, 1697);
      setCapturedImages(prev => [...prev, resultCanvas.toDataURL('image/jpeg', 0.85)]);
    } catch (e) {
      console.warn("Auto-crop failed, using full frame.");
      setCapturedImages(prev => [...prev, canvas.toDataURL('image/jpeg', 0.85)]);
    }
  };

  const generatePDF = () => {
    if (capturedImages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Building PDF...' });

    try {
      const { jsPDF } = jspdf;
      const doc = new jsPDF('p', 'mm', 'a4');

      capturedImages.forEach((img, idx) => {
        if (idx > 0) doc.addPage();
        // A4: 210 x 297 mm
        doc.addImage(img, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
      });

      const blob = doc.output('blob');
      const url = URL.createObjectURL(blob);
      setState({ 
        status: 'success', 
        progress: 100, 
        resultUrl: url, 
        resultFileName: `scan_${Date.now()}.pdf` 
      });
      stopCamera();
    } catch (error) {
      setState({ status: 'error', progress: 0, message: 'PDF creation failed.' });
    }
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 transition-colors duration-300">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-[900] text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Document Scan</h1>
        <p className="text-slate-500 dark:text-slate-400 font-medium">Capture high-quality PDF scans with your camera.</p>

        {!isScannerReady && (
          <div className="mt-8 bg-teal-50 dark:bg-teal-900/20 px-6 py-3 rounded-full inline-flex items-center gap-3 border border-teal-500/20">
            <i className="fas fa-circle-notch fa-spin text-teal-600"></i>
            <span className="text-[10px] font-black uppercase tracking-widest text-teal-600 dark:text-teal-400">Loading Scanning Engine...</span>
          </div>
        )}
      </div>

      {!stream && state.status !== 'success' && (
        <div className="bg-white dark:bg-slate-900 p-16 md:p-24 rounded-[3.5rem] border-4 border-dashed border-slate-100 dark:border-slate-800 text-center shadow-2xl flex flex-col items-center animate-in fade-in zoom-in duration-500">
          <div className="w-24 h-24 bg-teal-50 dark:bg-teal-900/30 text-teal-600 dark:text-teal-400 rounded-[2.5rem] flex items-center justify-center text-4xl mb-8 shadow-inner">
            <i className="fas fa-camera"></i>
          </div>
          <button 
            onClick={startCamera} 
            disabled={!isScannerReady}
            className="bg-teal-600 text-white px-12 py-5 rounded-3xl font-black text-xl shadow-xl shadow-teal-500/30 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-wait"
          >
            Launch Scanner
          </button>
          <p className="mt-8 text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest">Client-side scanning • Private & Secure</p>
        </div>
      )}

      {stream && (
        <div className="relative rounded-[3rem] overflow-hidden bg-black aspect-[3/4] max-w-lg mx-auto ring-[16px] ring-white dark:ring-slate-900 shadow-2xl animate-in zoom-in duration-500">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="w-full h-full object-cover"
          ></video>
          <canvas ref={canvasRef} className="hidden"></canvas>

          {/* Scanning Overlay */}
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-full h-full border-[40px] border-black/30 flex items-center justify-center">
                <div className="w-full h-full border-2 border-dashed border-white/50 rounded-2xl relative">
                   <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-teal-400 rounded-tl-xl"></div>
                   <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-teal-400 rounded-tr-xl"></div>
                   <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-teal-400 rounded-bl-xl"></div>
                   <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-teal-400 rounded-br-xl"></div>
                </div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-8 z-20 px-6">
            <button 
              onClick={captureFrame} 
              className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-teal-600 text-3xl shadow-2xl border-4 border-teal-500/20 active:scale-90 transition-all hover:bg-teal-50"
            >
              <i className="fas fa-camera"></i>
            </button>

            {capturedImages.length > 0 && (
              <button 
                onClick={generatePDF} 
                className="bg-teal-600 text-white px-8 py-5 rounded-2xl font-black text-sm shadow-xl flex items-center gap-3 active:scale-95 transition-all"
              >
                Save <span className="bg-white/20 px-2 py-0.5 rounded text-[10px] font-black">{capturedImages.length}</span>
