            >
               <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      {capturedImages.length > 0 && (
        <div className="mt-16 animate-in slide-in-from-bottom-10 duration-500">
          <h3 className="text-[11px] font-[900] text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em] text-center mb-8">Session Gallery</h3>
          <div className="flex gap-4 overflow-x-auto pb-8 no-scrollbar px-4">
              {capturedImages.map((img, i) => (
