        <div className="flex-1 flex flex-col items-center justify-center p-12 bg-slate-50 dark:bg-slate-950 text-center animate-in zoom-in duration-500">
           <div className="w-24 h-24 bg-teal-500 text-white text-4xl rounded-[2.5rem] flex items-center justify-center mb-8 shadow-2xl shadow-teal-500/30 border-4 border-white dark:border-slate-800">
             <i className="fas fa-check-double"></i>
           </div>
           <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 uppercase tracking-tighter leading-none">PDF Created!</h2>
           <p className="text-slate-500 dark:text-slate-400 mb-12 font-medium text-lg leading-relaxed max-w-xs mx-auto uppercase tracking-widest text-[10px] opacity-60">Professional High-Fidelity Output</p>

           <div className="flex flex-col gap-4 w-full max-w-xs">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white py-6 rounded-[2rem] font-black text-xl shadow-xl shadow-orange-500/30 active:scale-95 transition-all flex items-center justify-center gap-4 group">
                <i className="fas fa-download group-hover:animate-bounce"></i> DOWNLOAD PDF
              </a>
              <button onClick={() => { setCapturedPages([]); setState({status:'idle', progress: 0}); setUiStep('idle'); }} className="text-slate-400 font-black text-[10px] uppercase tracking-[0.3em] py-4 hover:text-teal-600 transition-colors">
                Start New Session
              </button>
           </div>
        </div>
      )}

      {/* Processing State Overlay */}
      {state.status === 'processing' && (
        <div className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-2xl flex flex-col items-center justify-center p-12 text-center text-white">
           <div className="relative w-24 h-24 mb-10">
              <div className="absolute inset-0 border-8 border-white/5 rounded-full"></div>
              <div className="absolute inset-0 border-8 border-teal-500 border-t-transparent rounded-full animate-spin"></div>
           </div>
           <h2 className="text-2xl font-black mb-3 uppercase tracking-tighter">Optimizing...</h2>
           <p className="text-white/40 font-bold uppercase text-[10px] tracking-[0.4em] max-w-xs">{state.message}</p>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ProcessingState } from '../types';

declare const jspdf: any;

type ScanFilter = 'none' | 'document' | 'bw' | 'grayscale';
type ScanMode = 'document' | 'idcard' | 'book' | 'photo';

interface Point {
  x: number;
  y: number;
}

interface CapturedPage {
  original: string;
  processed: string;
  filter: ScanFilter;
}

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedPages, setCapturedPages] = useState<CapturedPage[]>([]);

  // UI Steps: 'idle' | 'camera' | 'crop' | 'edit' | 'gallery'
  const [uiStep, setUiStep] = useState<'camera' | 'crop' | 'edit' | 'gallery' | 'idle'>('idle');
  const [currentCapture, setCurrentCapture] = useState<string | null>(null);
  const [currentFilter, setCurrentFilter] = useState<ScanFilter>('document');
  const [currentMode, setCurrentMode] = useState<ScanMode>('document');

  // Cropping State
  const [cropPoints, setCropPoints] = useState<Point[]>([
    { x: 10, y: 10 }, { x: 90, y: 10 },
    { x: 90, y: 90 }, { x: 10, y: 90 }
  ]);
  const [draggingIdx, setDraggingIdx] = useState<number | null>(null);
  const cropContainerRef = useRef<HTMLDivElement>(null);

  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const startCamera = async () => {
    try {
      setState({ status: 'loading', progress: 0 });
      const constraints = {
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        }
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      setUiStep('camera');
      setState({ status: 'idle', progress: 0 });
    } catch (err) {
      alert("Camera access denied. Please allow permissions in settings.");
      setUiStep('idle');
    }
  };

  useEffect(() => {
    if (uiStep === 'camera' && stream && videoRef.current) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(console.error);
    }
  }, [uiStep, stream]);

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setUiStep('idle');
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(video, 0, 0);

    const rawData = canvas.toDataURL('image/jpeg', 0.95);
    setCurrentCapture(rawData);

    // Initialize crop points (15% margin)
    setCropPoints([
      { x: 15, y: 15 }, { x: 85, y: 15 },
      { x: 85, y: 85 }, { x: 15, y: 85 }
    ]);
    setUiStep('crop');
  };

  // Draggable Logic for Crop
  const handleTouchMove = (e: React.TouchEvent | React.MouseEvent) => {
    if (draggingIdx === null || !cropContainerRef.current) return;
    const rect = cropContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    const x = Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100));
    const y = Math.max(0, Math.min(100, ((clientY - rect.top) / rect.height) * 100));

    const newPoints = [...cropPoints];
    newPoints[draggingIdx] = { x, y };
    setCropPoints(newPoints);
  };

  const applyCropAndGoToEnhance = () => {
    if (!currentCapture || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = currentCapture;
    img.onload = () => {
      // For simplicity in this lightweight version, we perform a standard rectangular crop 
      // based on the min/max of the user points. 
      // Professional homography requires a 3x3 matrix multiplication (heavy).
      const minX = Math.min(...cropPoints.map(p => p.x)) * img.width / 100;
      const maxX = Math.max(...cropPoints.map(p => p.x)) * img.width / 100;
      const minY = Math.min(...cropPoints.map(p => p.y)) * img.height / 100;
      const maxY = Math.max(...cropPoints.map(p => p.y)) * img.height / 100;

      const cropWidth = maxX - minX;
      const cropHeight = maxY - minY;

      canvas.width = cropWidth;
      canvas.height = cropHeight;
      ctx.drawImage(img, minX, minY, cropWidth, cropHeight, 0, 0, cropWidth, cropHeight);

      setCurrentCapture(canvas.toDataURL('image/jpeg', 0.95));
      setUiStep('edit');
    };
  };

  const confirmFinalPage = () => {
    if (!currentCapture || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const img = new Image();
    img.src = currentCapture;
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Magic / Document Filtering Logic
      if (currentFilter === 'document') {
        for (let i = 0; i < data.length; i += 4) {
          const r = data[i], g = data[i+1], b = data[i+2];
          // Balanced Grayscale
          let gray = 0.21 * r + 0.72 * g + 0.07 * b;

          // Background Whitening & Contrast (Magic Filter)
          // Aggressive highlight stretch to remove yellow paper/shadows
          let val = (gray - 90) * 2.2 + 100;
          if (val > 210) val = 255; // Whiten background
          if (val < 60) val *= 0.6;   // Deepen text

          val = Math.max(0, Math.min(255, val));
          data[i] = data[i+1] = data[i+2] = val;
        }
      } else if (currentFilter === 'bw') {
        for (let i = 0; i < data.length; i += 4) {
          const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
          const val = avg > 120 ? 255 : 0;
          data[i] = data[i+1] = data[i+2] = val;
        }
      } else if (currentFilter === 'grayscale') {
        for (let i = 0; i < data.length; i += 4) {
          const g = 0.3 * data[i] + 0.59 * data[i + 1] + 0.11 * data[i + 2];
          data[i] = data[i+1] = data[i+2] = g;
        }
      }

      ctx.putImageData(imageData, 0, 0);
      const processedData = canvas.toDataURL('image/jpeg', 0.88);

      setCapturedPages(prev => [...prev, { 
        original: currentCapture, 
        processed: processedData, 
        filter: currentFilter 
      }]);

      setCurrentCapture(null);
      setUiStep('camera');
    };
  };

  const generatePDF = () => {
    if (capturedPages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: 'Compiling PDF...' });

    setTimeout(() => {
      try {
        const { jsPDF } = jspdf;
        const doc = new jsPDF('p', 'mm', 'a4');
        capturedPages.forEach((page, idx) => {
          if (idx > 0) doc.addPage();
          doc.addImage(page.processed, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
        });
        const blob = doc.output('blob');
        setState({ 
          status: 'success', 
          resultUrl: URL.createObjectURL(blob), 
          resultFileName: `scanner_${Date.now()}.pdf`,
          progress: 100 
        });
        stopCamera();
      } catch (e) {
        setState({ status: 'error', progress: 0, message: 'PDF export failed.' });
      }
    }, 100);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden select-none touch-none">
      <canvas ref={canvasRef} className="hidden"></canvas>

      {/* Camera View Step */}
      {uiStep === 'camera' && (
        <div className="flex-1 flex flex-col h-full animate-in fade-in duration-300">
          <div className="absolute top-0 inset-x-0 p-4 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent z-20">
            <button onClick={stopCamera} className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center text-white">
              <i className="fas fa-times"></i>
            </button>
            <div className="flex flex-col items-center">
              <span className="text-[10px] font-black tracking-[0.3em] uppercase text-teal-400">Scanner Active</span>
              <span className="text-white font-black text-xs uppercase">{capturedPages.length} PAGES READY</span>
            </div>
            <button className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center text-white">
              <i className="fas fa-bolt-auto"></i>
            </button>
          </div>

          <div className="flex-1 relative flex items-center justify-center overflow-hidden">
            <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover"></video>
            {/* Viewfinder Guide */}
            <div className="absolute inset-0 border-[40px] border-black/30 pointer-events-none">
               <div className="w-full h-full border-2 border-dashed border-teal-500/20 rounded-[2rem] relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-teal-500 rounded-tl-2xl"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-teal-500 rounded-tr-2xl"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-teal-500 rounded-bl-2xl"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-teal-500 rounded-br-2xl"></div>
               </div>
            </div>
          </div>

          <div className="bg-black/90 px-6 pt-4 pb-10 flex flex-col gap-6">
            <div className="flex gap-4 overflow-x-auto no-scrollbar py-2 mask-fade-edges">
               {['DOCUMENT', 'ID CARD', 'BOOK', 'PHOTO'].map(m => (
                 <button 
                  key={m} 
                  className={`text-[9px] font-black tracking-widest uppercase whitespace-nowrap px-6 py-2.5 rounded-full border transition-all ${m.toLowerCase().replace(' ','') === currentMode ? 'bg-teal-500 text-black border-teal-500 shadow-lg shadow-teal-500/20' : 'text-slate-500 border-white/5 bg-white/5'}`}
                  onClick={() => setCurrentMode(m.toLowerCase().replace(' ','') as any)}
                 >
                   {m}
                 </button>
               ))}
            </div>

            <div className="flex items-center justify-between max-w-sm mx-auto w-full px-2">
               <button 
                 onClick={() => capturedPages.length > 0 && setUiStep('gallery')}
                 className="w-12 h-12 rounded-xl border border-white/10 overflow-hidden bg-white/5 flex items-center justify-center active:scale-90 transition-transform"
               >
                 {capturedPages.length > 0 ? (
                   <img src={capturedPages[capturedPages.length-1].processed} className="w-full h-full object-cover" />
                 ) : (
                   <i className="fas fa-images text-slate-800"></i>
                 )}
               </button>

               <button onClick={capturePhoto} className="w-20 h-20 rounded-full border-4 border-white/20 p-1 active:scale-95 transition-all shadow-[0_0_30px_rgba(20,184,166,0.3)]">
                  <div className="w-full h-full bg-white rounded-full flex items-center justify-center">
                    <div className="w-16 h-16 rounded-full border-2 border-black/5 flex items-center justify-center">
                       <i className="fas fa-camera text-black text-xl"></i>
                    </div>
                  </div>
               </button>

               <button 
                 onClick={() => capturedPages.length > 0 && setUiStep('gallery')}
                 disabled={capturedPages.length === 0}
                 className={`w-12 h-12 rounded-xl flex items-center justify-center text-xl transition-all ${capturedPages.length > 0 ? 'bg-teal-600 text-white shadow-lg shadow-teal-500/20' : 'bg-white/5 text-slate-800 pointer-events-none'}`}
               >
                 <i className="fas fa-check"></i>
               </button>
            </div>
          </div>
        </div>
      )}

      {/* Crop Step */}
      {uiStep === 'crop' && currentCapture && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in slide-in-from-right duration-300">
          <div className="p-4 flex justify-between items-center bg-black/50 border-b border-white/5">
            <button onClick={() => setUiStep('camera')} className="text-slate-400 font-black text-[10px] uppercase tracking-widest"><i className="fas fa-arrow-left mr-2"></i> Retake</button>
            <h2 className="text-white font-black text-xs uppercase tracking-[0.4em]">Adjust Borders</h2>
            <button onClick={applyCropAndGoToEnhance} className="text-teal-400 font-black text-[10px] uppercase tracking-widest">Next <i className="fas fa-arrow-right ml-1"></i></button>
          </div>

          <div className="flex-1 relative p-6 flex items-center justify-center" ref={cropContainerRef}
               onTouchMove={handleTouchMove} onMouseMove={(e) => draggingIdx !== null && handleTouchMove(e as any)}>
            <img src={currentCapture} className="max-w-full max-h-full object-contain shadow-2xl rounded-lg pointer-events-none" />

            {/* Draggable Points & Lines Overlay */}
            <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
               <polygon 
                 points={cropPoints.map(p => `${p.x}%,${p.y}%`).join(' ')} 
                 className="fill-teal-500/10 stroke-teal-500 stroke-2" 
               />
            </svg>

            {cropPoints.map((p, i) => (
              <div 
                key={i}
                className="absolute w-10 h-10 -ml-5 -mt-5 bg-teal-500/20 rounded-full flex items-center justify-center touch-none pointer-events-auto"
                style={{ left: `${p.x}%`, top: `${p.y}%` }}
                onPointerDown={() => setDraggingIdx(i)}
                onPointerUp={() => setDraggingIdx(null)}
              >
                <div className="w-6 h-6 bg-white rounded-full border-4 border-teal-500 shadow-xl"></div>
              </div>
            ))}
          </div>

          <div className="p-6 text-center text-[10px] font-bold text-slate-500 uppercase tracking-widest bg-black/40">
            Drag corners to match your document
          </div>
        </div>
      )}

      {/* Enhance Step */}
      {uiStep === 'edit' && currentCapture && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in slide-in-from-bottom duration-300">
           <div className="p-4 flex justify-between items-center bg-black/50 border-b border-white/5">
              <button onClick={() => setUiStep('crop')} className="text-slate-400 font-black text-[10px] uppercase tracking-widest"><i className="fas fa-arrow-left mr-2"></i> Back</button>
              <h2 className="text-white font-black text-xs uppercase tracking-[0.4em]">Enhance Scan</h2>
              <button onClick={confirmFinalPage} className="bg-teal-600 text-white px-5 py-2 rounded-lg font-black text-[10px] uppercase tracking-widest shadow-lg active:scale-95 transition-all">Accept</button>
           </div>

           <div className="flex-1 p-6 flex items-center justify-center overflow-hidden">
              <img 
                src={currentCapture} 
                className={`max-w-full max-h-full object-contain transition-all duration-300 shadow-2xl ${currentFilter === 'document' ? 'contrast-[1.2] grayscale' : currentFilter === 'bw' ? 'grayscale contrast-[2]' : currentFilter === 'grayscale' ? 'grayscale' : ''}`} 
              />
           </div>

           <div className="bg-black/95 p-6 grid grid-cols-4 gap-3 border-t border-white/5 pb-12">
              {[
                { id: 'none', label: 'Original', icon: 'fa-image' },
                { id: 'document', label: 'Magic', icon: 'fa-wand-magic-sparkles' },
                { id: 'bw', label: 'B&W', icon: 'fa-circle-half-stroke' },
                { id: 'grayscale', label: 'Gray', icon: 'fa-ghost' },
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setCurrentFilter(f.id as any)}
                  className={`flex flex-col items-center gap-3 p-4 rounded-2xl transition-all border ${currentFilter === f.id ? 'bg-teal-600 border-teal-500 text-black shadow-xl scale-105' : 'bg-white/5 border-white/5 text-slate-500'}`}
                >
                  <i className={`fas ${f.icon} text-lg`}></i>
                  <span className="text-[9px] font-black uppercase tracking-tighter">{f.label}</span>
                </button>
              ))}
           </div>
        </div>
      )}

      {/* Gallery Step */}
      {uiStep === 'gallery' && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden">
           <div className="p-4 flex justify-between items-center bg-black/50 border-b border-white/5">
              <button onClick={() => setUiStep('camera')} className="text-slate-400 font-black text-[10px] uppercase tracking-widest px-4 py-2 rounded-lg bg-white/5"><i className="fas fa-plus mr-2"></i> Scan More</button>
              <h2 className="text-white font-black text-xs uppercase tracking-[0.3em]">{capturedPages.length} Pages</h2>
              <button onClick={generatePDF} className="bg-teal-600 text-white px-5 py-2 rounded-lg font-black text-[10px] uppercase tracking-widest shadow-lg">Save PDF</button>
           </div>

           <div className="flex-1 p-6 grid grid-cols-2 gap-6 overflow-y-auto no-scrollbar">
              {capturedPages.map((p, i) => (
                <div key={i} className="relative aspect-[3/4] bg-white/5 rounded-2xl overflow-hidden border border-white/10 shadow-2xl group animate-in slide-in-from-bottom-4 duration-300">
                   <img src={p.processed} className="w-full h-full object-cover" />
                   <div className="absolute top-3 left-3 bg-black/60 backdrop-blur-md text-white text-[9px] font-black px-2 py-0.5 rounded-lg border border-white/10">PG {i+1}</div>
                   <button 
                     onClick={() => setCapturedPages(prev => prev.filter((_, idx) => idx !== i))}
                     className="absolute top-3 right-3 w-8 h-8 bg-rose-500 text-white rounded-full flex items-center justify-center text-xs opacity-100 transition-all shadow-xl active:scale-90"
                   >
                     <i className="fas fa-trash"></i>
                   </button>
                </div>
              ))}
           </div>

           <div className="p-8 bg-black/90 border-t border-white/5 pb-12">
              <button onClick={generatePDF} className="w-full bg-teal-600 text-white py-5 rounded-2xl font-black text-lg shadow-2xl shadow-teal-500/20 active:scale-95 transition-all flex items-center justify-center gap-4">
                <i className="fas fa-file-pdf"></i> FINISH & EXPORT
              </button>
           </div>
        </div>
      )}

      {/* Idle / Initial State (if called outside immersive flow) */}
      {uiStep === 'idle' && (
        <div className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-slate-50 dark:bg-slate-950 animate-in fade-in duration-500">
           <div className="w-24 h-24 bg-teal-500 text-white rounded-[2rem] flex items-center justify-center text-4xl mb-6 shadow-xl shadow-teal-500/20">
             <i className="fas fa-camera"></i>
           </div>
           <h1 className="text-3xl font-black text-slate-900 dark:text-white mb-2 uppercase tracking-tighter leading-none">Pro Document Scanner</h1>
           <p className="text-slate-500 dark:text-slate-400 mb-10 text-sm max-w-xs font-medium uppercase tracking-[0.3em] opacity-60">High contrast • Edge detection • PDF export</p>
           <button onClick={startCamera} className="bg-teal-600 text-white px-12 py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all">
             Start Scanning
           </button>
        </div>
      )}

      {/* Result View */}
      {state.status === 'success' && (
        <div className="fixed inset-0 z-[200] bg-white dark:bg-slate-950 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in duration-500">
           <div className="w-24 h-24 bg-teal-500 text-white text-4xl rounded-[2.5rem] flex items-center justify-center mb-10 shadow-2xl shadow-teal-500/30">
             <i className="fas fa-check-double"></i>
           </div>
           <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 uppercase tracking-tighter leading-none">PDF Created!</h2>
           <p className="text-slate-500 dark:text-slate-400 mb-12 font-medium text-lg leading-relaxed max-w-xs mx-auto uppercase tracking-widest text-[10px] opacity-60">Professional Output Ready</p>

           <div className="flex flex-col gap-4 w-full max-w-xs">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white py-6 rounded-2xl font-black text-xl shadow-xl shadow-orange-500/30 active:scale-95 transition-all flex items-center justify-center gap-4">
                <i className="fas fa-download"></i> DOWNLOAD
              </a>
              <button onClick={() => { setCapturedPages([]); setState({status:'idle', progress: 0}); setUiStep('idle'); }} className="text-slate-400 font-black text-[10px] uppercase tracking-[0.3em] py-4">
                New Session
              </button>
           </div>
        </div>
      )}

      {state.status === 'processing' && (
        <div className="fixed inset-0 z-[300] bg-black/95 backdrop-blur-2xl flex flex-col items-center justify-center p-12 text-center text-white">
           <div className="w-16 h-16 border-[5px] border-white/10 border-t-teal-500 rounded-full animate-spin mb-8"></div>
           <h2 className="text-2xl font-black mb-2 uppercase tracking-tighter">Optimizing...</h2>
           <p className="text-white/40 font-bold uppercase text-[9px] tracking-[0.4em]">{state.message}</p>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState, useEffect } from 'react';
