      )}

      {/* Crop Step */}
      {uiStep === 'crop' && currentCapture && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in slide-in-from-right duration-300">
           <div className="p-4 pt-8 flex justify-between items-center bg-black/50 border-b border-white/5">
              <button onClick={() => setUiStep('camera')} className="flex items-center gap-2 text-slate-400 font-black text-[10px] uppercase tracking-widest px-4 py-2 rounded-xl bg-white/5 active:scale-90 transition-all">
                <i className="fas fa-arrow-left"></i> Retake
              </button>
              <h2 className="text-white font-black text-xs uppercase tracking-[0.4em]">Detect Edges</h2>
              <button onClick={applyCrop} className="bg-teal-600 text-white px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg active:scale-95 transition-all">
                Next Step <i className="fas fa-arrow-right ml-1"></i>
              </button>
           </div>
           <div className="flex-1 relative p-8 flex items-center justify-center" ref={cropContainerRef} onTouchMove={handlePointMove}>
              <img src={currentCapture} className="max-w-full max-h-full object-contain shadow-2xl rounded-xl pointer-events-none opacity-80" />
              <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
                 <polygon points={cropPoints.map(p => `${p.x}%,${p.y}%`).join(' ')} className="fill-teal-500/20 stroke-teal-500 stroke-4" />
              </svg>
              {cropPoints.map((p, i) => (
                <div key={i} className="absolute w-14 h-14 -ml-7 -mt-7 rounded-full flex items-center justify-center touch-none active:scale-150 transition-transform" style={{ left: `${p.x}%`, top: `${p.y}%` }} onPointerDown={() => setDraggingIdx(i)} onPointerUp={() => setDraggingIdx(null)}>
                  <div className="w-8 h-8 bg-white/30 backdrop-blur-xl rounded-full border-4 border-teal-500 shadow-2xl flex items-center justify-center">
                    <div className="w-1.5 h-1.5 bg-teal-500 rounded-full"></div>
                  </div>
                </div>
              ))}
           </div>
           <div className="p-10 text-center bg-black/60 border-t border-white/5">
              <p className="text-[10px] font-black uppercase tracking-[0.5em] text-teal-400">Drag to snap to document corners</p>
           </div>
        </div>
      )}

      {/* Edit / Filters Step */}
      {uiStep === 'edit' && currentCapture && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in slide-in-from-bottom duration-300">
           <div className="p-4 pt-8 flex justify-between items-center bg-black/50 border-b border-white/5 shadow-2xl">
              <button onClick={() => setUiStep('crop')} className="flex items-center gap-2 text-slate-400 font-black text-[10px] uppercase tracking-widest px-4 py-2 rounded-xl bg-white/5 active:scale-90 transition-all">
                <i className="fas fa-arrow-left"></i> Crop
              </button>
              <h2 className="text-white font-black text-xs uppercase tracking-[0.4em]">Apply Filters</h2>
              <button onClick={acceptEnhancedPage} className="bg-teal-600 text-white px-8 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-2xl active:scale-95 transition-all">
                Accept <i className="fas fa-check ml-1"></i>
              </button>
           </div>
           <div className="flex-1 p-8 flex items-center justify-center overflow-hidden">
              <img src={currentCapture} className={`max-w-full max-h-full object-contain transition-all duration-300 shadow-2xl rounded-xl border border-white/10 ${currentFilter === 'document' ? 'contrast-[1.25] grayscale brightness-110' : currentFilter === 'magic_color' ? 'contrast-[1.2] brightness-105 saturate-[1.4]' : currentFilter === 'bw' ? 'grayscale contrast-[2.5]' : currentFilter === 'grayscale' ? 'grayscale' : ''}`} />
           </div>
           <div className="bg-black/90 p-6 flex gap-4 overflow-x-auto no-scrollbar border-t border-white/5 pb-14 mask-fade-edges">
              {[
                { id: 'none', label: 'ORIGINAL', icon: 'fa-image' },
                { id: 'document', label: 'MAGIC B&W', icon: 'fa-wand-magic-sparkles' },
                { id: 'magic_color', label: 'MAGIC COLOR', icon: 'fa-palette' },
                { id: 'bw', label: 'SHARP B&W', icon: 'fa-circle-half-stroke' },
                { id: 'grayscale', label: 'GRAYSCALE', icon: 'fa-ghost' },
              ].map(f => (
                <button key={f.id} onClick={() => setCurrentFilter(f.id as any)} className={`flex flex-col items-center gap-3 p-5 min-w-[100px] rounded-3xl transition-all border-2 ${currentFilter === f.id ? 'bg-teal-600 border-teal-500 text-black shadow-2xl scale-105' : 'bg-white/5 border-white/5 text-slate-500 hover:border-white/10'}`}>
                  <i className={`fas ${f.icon} text-xl`}></i>
                  <span className="text-[9px] font-black uppercase tracking-tighter whitespace-nowrap">{f.label}</span>
                </button>
              ))}
           </div>
        </div>
      )}

      {/* Processing / Result States */}
      {uiStep === 'idle' && state.status !== 'success' && (
        <div className="flex-1 flex flex-col items-center justify-center p-12 text-center bg-slate-950 h-full">
           <div className="w-28 h-28 bg-teal-500/10 text-teal-500 rounded-[2.5rem] flex items-center justify-center text-5xl mb-10 border border-teal-500/20 shadow-2xl">
             <i className="fas fa-camera"></i>
           </div>
           <h1 className="text-4xl font-black text-white mb-4 uppercase tracking-tighter">Pro Scanner</h1>
           <p className="text-slate-500 mb-12 font-medium text-sm max-w-xs mx-auto uppercase tracking-[0.3em]">Privacy-First • Local Export</p>
           <button onClick={startCamera} className="bg-teal-600 text-white px-14 py-6 rounded-3xl font-black text-xl shadow-2xl shadow-teal-600/20 active:scale-95 transition-all">Start Scanning</button>
        </div>
      )}

      {state.status === 'success' && (
        <div className="fixed inset-0 z-[99999] bg-slate-950 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in duration-500">
           <div className="w-28 h-28 bg-teal-500 text-white text-5xl rounded-[3rem] flex items-center justify-center mb-12 shadow-2xl shadow-teal-500/40 border-4 border-white/10">
             <i className="fas fa-check-double"></i>
           </div>
           <h2 className="text-5xl font-black text-white mb-6 uppercase tracking-tighter">SUCCESS!</h2>
           <p className="text-slate-500 mb-14 font-black text-xs uppercase tracking-[0.5em] opacity-80">Document Exported Locally</p>
           <div className="flex flex-col gap-5 w-full max-w-sm">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white py-7 rounded-[2.5rem] font-black text-2xl shadow-2xl shadow-orange-500/30 active:scale-95 transition-all flex items-center justify-center gap-5 group">
                <i className="fas fa-file-download group-hover:animate-bounce"></i> DOWNLOAD
              </a>
              <button onClick={() => { setCapturedPages([]); setState({status:'idle', progress: 0}); setUiStep('idle'); }} className="text-slate-500 font-black text-[11px] uppercase tracking-[0.4em] py-6 hover:text-teal-500 transition-colors active:scale-95">
                START NEW SESSION
              </button>
           </div>
        </div>
      )}

      {state.status === 'processing' && (
        <div className="fixed inset-0 z-[30000] bg-black/95 backdrop-blur-3xl flex flex-col items-center justify-center p-12 text-center text-white">
           <div className="relative w-28 h-28 mb-12">
              <div className="absolute inset-0 border-[10px] border-white/5 rounded-full"></div>
              <div className="absolute inset-0 border-[10px] border-teal-500 border-t-transparent rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center text-teal-500 text-xl font-black">{state.progress}%</div>
           </div>
           <h2 className="text-3xl font-black mb-4 uppercase tracking-tighter">Optimizing...</h2>
           <p className="text-white/40 font-black uppercase text-[10px] tracking-[0.6em] max-w-xs leading-loose">{state.message}</p>
        </div>
      )}
    </div>
  );
};

export default Scan;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ProcessingState } from '../types';

// Access jspdf from the window object (UMD build)
declare const jspdf: any;

type ScanFilter = 'none' | 'document' | 'magic_color' | 'bw' | 'grayscale';
type ScanMode = 'document' | 'idcard' | 'book' | 'photo';

interface Point {
  x: number;
  y: number;
}

interface CapturedPage {
  original: string;
  processed: string;
  filter: ScanFilter;
  id: string;
}

const Scan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const cropCanvasRef = useRef<HTMLCanvasElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedPages, setCapturedPages] = useState<CapturedPage[]>([]);

  // UI Steps: 'camera' | 'crop' | 'edit' | 'gallery' | 'idle'
  const [uiStep, setUiStep] = useState<'camera' | 'crop' | 'edit' | 'gallery' | 'idle'>('idle');

  const [currentCapture, setCurrentCapture] = useState<string | null>(null);
  const [currentFilter, setCurrentFilter] = useState<ScanFilter>('document');
  const [currentMode, setCurrentMode] = useState<ScanMode>('document');
  const [isFlashOn, setIsFlashOn] = useState(false);

  const [fileName, setFileName] = useState(`Scan_${new Date().toLocaleDateString().replace(/\//g, '-')}`);
  const [isRenaming, setIsRenaming] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<'PDF' | 'JPG'>('PDF');
  const [compressionQuality, setCompressionQuality] = useState(80);
  const [pageSize, setPageSize] = useState<'A4' | 'Auto'>('A4');
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Cropping State
  const [cropPoints, setCropPoints] = useState<Point[]>([
    { x: 15, y: 15 }, { x: 85, y: 15 },
    { x: 85, y: 85 }, { x: 15, y: 85 }
  ]);
  const [draggingIdx, setDraggingIdx] = useState<number | null>(null);
  const cropContainerRef = useRef<HTMLDivElement>(null);

  const [state, setState] = useState<ProcessingState>({ status: 'idle', progress: 0 });

  const startCamera = async () => {
    try {
      setState({ status: 'loading', progress: 0 });
      // Simplified constraints to avoid OverconstrainedError
      const constraints = {
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      setUiStep('camera');
      setState({ status: 'idle', progress: 0 });
    } catch (err) {
      console.error("Camera error:", err);
      alert("Unable to access camera. Please ensure permissions are granted.");
      setUiStep('idle');
      setState({ status: 'idle', progress: 0 });
    }
  };

  const toggleFlash = async () => {
    if (!stream) return;
    const track = stream.getVideoTracks()[0];
    const capabilities = (track as any).getCapabilities?.() || {};

    if (capabilities.torch) {
      try {
        const nextFlash = !isFlashOn;
        await (track as any).applyConstraints({
          advanced: [{ torch: nextFlash }]
        });
        setIsFlashOn(nextFlash);
      } catch (err) {
        console.error("Flash error:", err);
      }
    } else {
      alert("Flashlight is not available on this camera.");
    }
  };

  useEffect(() => {
    if (uiStep === 'camera' && stream && videoRef.current) {
      videoRef.current.srcObject = stream;
      const playPromise = videoRef.current.play();
      if (playPromise !== undefined) {
        playPromise.catch(error => console.error("Video play failed:", error));
      }
    }
  }, [uiStep, stream]);

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setUiStep('idle');
    setIsFlashOn(false);
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const video = videoRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(video, 0, 0);

    // Visual feedback (flash)
    const flashOverlay = document.createElement('div');
    flashOverlay.className = 'fixed inset-0 bg-white z-[99999] animate-pulse pointer-events-none';
    document.body.appendChild(flashOverlay);
    setTimeout(() => flashOverlay.remove(), 80);

    const rawData = canvas.toDataURL('image/jpeg', 0.95);
    setCurrentCapture(rawData);
    // Reset crop points for new capture
    setCropPoints([{ x: 15, y: 15 }, { x: 85, y: 15 }, { x: 85, y: 85 }, { x: 15, y: 85 }]);
    setUiStep('crop');
  };

  const handlePointMove = useCallback((e: React.TouchEvent | React.MouseEvent) => {
    if (draggingIdx === null || !cropContainerRef.current) return;
    const rect = cropContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    const x = Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100));
    const y = Math.max(0, Math.min(100, ((clientY - rect.top) / rect.height) * 100));

    const newPoints = [...cropPoints];
    newPoints[draggingIdx] = { x, y };
    setCropPoints(newPoints);
  }, [draggingIdx, cropPoints]);

  const applyCrop = () => {
    if (!currentCapture || !cropCanvasRef.current) return;
    const canvas = cropCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = currentCapture;
    img.onload = () => {
      // Logic for simple quadrilateral crop based on our bounding box
      const minX = Math.min(...cropPoints.map(p => p.x)) * img.width / 100;
      const maxX = Math.max(...cropPoints.map(p => p.x)) * img.width / 100;
      const minY = Math.min(...cropPoints.map(p => p.y)) * img.height / 100;
      const maxY = Math.max(...cropPoints.map(p => p.y)) * img.height / 100;

      const cropWidth = maxX - minX;
      const cropHeight = maxY - minY;

      canvas.width = cropWidth;
      canvas.height = cropHeight;
      ctx.drawImage(img, minX, minY, cropWidth, cropHeight, 0, 0, cropWidth, cropHeight);

      setCurrentCapture(canvas.toDataURL('image/jpeg', 0.95));
      setUiStep('edit');
    };
  };

  const acceptEnhancedPage = () => {
    if (!currentCapture || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) return;

    const img = new Image();
    img.src = currentCapture;
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Professional Document Filters
      if (currentFilter === 'document') {
        for (let i = 0; i < data.length; i += 4) {
          let gray = 0.2126 * data[i] + 0.7152 * data[i+1] + 0.0722 * data[i+2];
          let val = (gray - 110) * 2.5 + 128;
          val = Math.max(0, Math.min(255, val > 200 ? 255 : val < 60 ? val * 0.5 : val));
          data[i] = data[i+1] = data[i+2] = val;
        }
      } else if (currentFilter === 'bw') {
        for (let i = 0; i < data.length; i += 4) {
          const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
          const val = avg > 115 ? 255 : 0;
          data[i] = data[i+1] = data[i+2] = val;
        }
      } else if (currentFilter === 'grayscale') {
        for (let i = 0; i < data.length; i += 4) {
          const g = 0.3 * data[i] + 0.59 * data[i + 1] + 0.11 * data[i + 2];
          data[i] = data[i+1] = data[i+2] = g;
        }
      }

      ctx.putImageData(imageData, 0, 0);
      const processedData = canvas.toDataURL('image/jpeg', compressionQuality / 100);

      setCapturedPages(prev => [...prev, { 
        original: currentCapture, 
        processed: processedData, 
        filter: currentFilter,
        id: Math.random().toString(36).substr(2, 9)
      }]);
      setCurrentCapture(null);
      setUiStep('camera');
    };
  };

  const performExport = () => {
    if (capturedPages.length === 0) return;
    setState({ status: 'processing', progress: 50, message: `Building your ${exportFormat}...` });
    setShowShareModal(false);

    // Defer for UI update
    setTimeout(() => {
      try {
        const { jsPDF } = (window as any).jspdf;
        if (exportFormat === 'PDF') {
          const doc = new jsPDF('p', 'mm', pageSize === 'A4' ? 'a4' : [210, 297]);
          const pw = 210, ph = 297;

          capturedPages.forEach((page, idx) => {
            if (idx > 0) doc.addPage();
            doc.addImage(page.processed, 'JPEG', 0, 0, pw, ph, undefined, 'FAST');
          });

          const blob = doc.output('blob');
          setState({ 
            status: 'success', 
            resultUrl: URL.createObjectURL(blob), 
            resultFileName: `${fileName}.pdf`,
            progress: 100 
          });
        } else {
          // Export JPG (first page)
          setState({ 
            status: 'success', 
            resultUrl: capturedPages[0].processed, 
            resultFileName: `${fileName}.jpg`,
            progress: 100 
          });
        }
        stopCamera();
      } catch (e) {
        console.error("Export error:", e);
        setState({ status: 'error', progress: 0, message: 'Export failed. Try again.' });
      }
    }, 150);
  };

  const deleteSelected = () => {
    setCapturedPages(prev => prev.filter(p => !selectedIds.has(p.id)));
    setSelectedIds(new Set());
    setIsSelectMode(false);
  };

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  return (
    <div className="fixed inset-0 z-[9999] bg-white dark:bg-slate-950 flex flex-col overflow-hidden h-screen w-screen select-none">
      <canvas ref={canvasRef} className="hidden"></canvas>
      <canvas ref={cropCanvasRef} className="hidden"></canvas>

      {/* Camera UI Step */}
      {uiStep === 'camera' && (
        <div className="flex-1 flex flex-col h-full bg-black relative animate-in fade-in duration-300">
          <div className="absolute top-0 left-0 right-0 px-4 pt-6 pb-12 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent z-20">
            <button 
              onClick={stopCamera} 
              className="w-10 h-10 flex items-center justify-center rounded-full bg-white/20 backdrop-blur-md active:scale-90 transition-transform"
            >
              <i className="fas fa-times text-white"></i>
            </button>
            <div className="flex flex-col items-center">
               <span className="text-teal-400 font-black text-[10px] tracking-widest uppercase">Scanner</span>
               <span className="text-white font-black text-xs uppercase">{capturedPages.length} PAGES</span>
            </div>
            <button 
              onClick={toggleFlash} 
              className={`w-10 h-10 flex items-center justify-center rounded-full backdrop-blur-md active:scale-90 transition-all ${isFlashOn ? 'bg-orange-500 text-white shadow-lg shadow-orange-500/50' : 'bg-white/20 text-white'}`}
            >
              <i className={`fas ${isFlashOn ? 'fa-bolt' : 'fa-bolt-slash'}`}></i>
            </button>
          </div>

          <div className="flex-1 relative flex items-center justify-center overflow-hidden">
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover"
            ></video>
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="w-[85%] h-[65%] border-2 border-dashed border-teal-500/30 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-teal-500 rounded-tl-2xl"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-teal-500 rounded-tr-2xl"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-teal-500 rounded-bl-2xl"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-teal-500 rounded-br-2xl"></div>
              </div>
            </div>
          </div>

          <div className="bg-black/95 px-6 pt-4 pb-12 flex flex-col gap-6 z-20">
            <div className="flex gap-4 overflow-x-auto no-scrollbar py-1">
               {['DOCUMENT', 'ID CARD', 'BOOK', 'PHOTO'].map(m => (
                 <button 
                  key={m} 
                  className={`text-[10px] font-black tracking-widest uppercase whitespace-nowrap px-6 py-2.5 rounded-full border transition-all ${m.toLowerCase().replace(' ','') === currentMode ? 'bg-teal-500 text-black border-teal-500 shadow-xl' : 'text-slate-500 border-white/5 bg-white/5'}`} 
                  onClick={() => setCurrentMode(m.toLowerCase().replace(' ','') as any)}
                 >
                   {m}
                 </button>
               ))}
            </div>
            <div className="flex items-center justify-between max-w-sm mx-auto w-full px-2">
               <button 
                onClick={() => capturedPages.length > 0 && setUiStep('gallery')} 
                className="w-14 h-14 rounded-2xl border-2 border-white/10 overflow-hidden bg-white/5 flex items-center justify-center active:scale-90 transition-transform"
               >
                 {capturedPages.length > 0 ? <img src={capturedPages[capturedPages.length-1].processed} className="w-full h-full object-cover" /> : <i className="fas fa-images text-slate-800"></i>}
               </button>
               <button 
                onClick={capturePhoto} 
                className="w-24 h-24 rounded-full border-4 border-white/30 p-1 active:scale-95 transition-all shadow-2xl bg-white/5"
               >
                  <div className="w-full h-full bg-white rounded-full flex items-center justify-center">
                    <i className="fas fa-camera text-slate-900 text-2xl"></i>
                  </div>
               </button>
               <button 
                onClick={() => capturedPages.length > 0 && setUiStep('gallery')} 
                disabled={capturedPages.length === 0} 
                className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl transition-all ${capturedPages.length > 0 ? 'bg-teal-600 text-white shadow-xl active:scale-90' : 'bg-white/5 text-slate-800 pointer-events-none'}`}
               >
                 <i className="fas fa-check"></i>
               </button>
            </div>
          </div>
        </div>
      )}

      {/* Crop UI Step */}
      {uiStep === 'crop' && currentCapture && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in slide-in-from-right duration-300">
           <div className="p-4 pt-8 flex justify-between items-center bg-black/50 border-b border-white/5">
              <button 
                onClick={() => setUiStep('camera')} 
                className="flex items-center gap-2 text-slate-400 font-black text-[10px] uppercase tracking-widest px-4 py-2 rounded-xl bg-white/5 active:scale-90 transition-transform"
              >
                <i className="fas fa-arrow-left"></i> Retake
              </button>
              <h2 className="text-white font-black text-xs uppercase tracking-[0.4em]">Detect Edges</h2>
              <button 
                onClick={applyCrop} 
                className="bg-teal-600 text-white px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg active:scale-95 transition-transform"
              >
                Next <i className="fas fa-arrow-right ml-1"></i>
              </button>
           </div>
           <div 
            className="flex-1 relative p-8 flex items-center justify-center touch-none" 
            ref={cropContainerRef} 
            onMouseMove={handlePointMove}
            onTouchMove={handlePointMove}
           >
              <img src={currentCapture} className="max-w-full max-h-full object-contain shadow-2xl rounded-xl pointer-events-none opacity-80" />
              <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
                 <polygon points={cropPoints.map(p => `${p.x}%,${p.y}%`).join(' ')} className="fill-teal-500/20 stroke-teal-500 stroke-2" />
              </svg>
              {cropPoints.map((p, i) => (
                <div 
                  key={i} 
                  className="absolute w-12 h-12 -ml-6 -mt-6 rounded-full flex items-center justify-center touch-none transition-transform" 
                  style={{ left: `${p.x}%`, top: `${p.y}%`, cursor: draggingIdx === i ? 'grabbing' : 'grab' }} 
                  onMouseDown={() => setDraggingIdx(i)}
                  onMouseUp={() => setDraggingIdx(null)}
                  onTouchStart={() => setDraggingIdx(i)}
                  onTouchEnd={() => setDraggingIdx(null)}
                >
                  <div className={`w-6 h-6 bg-white rounded-full border-4 border-teal-500 shadow-xl transition-all ${draggingIdx === i ? 'scale-150' : ''}`}></div>
                </div>
              ))}
           </div>
           <div className="p-10 text-center bg-black/60 border-t border-white/5">
              <p className="text-[10px] font-black uppercase tracking-[0.5em] text-teal-400">Drag points to document corners</p>
           </div>
        </div>
      )}

      {/* Edit UI Step */}
      {uiStep === 'edit' && currentCapture && (
        <div className="flex-1 flex flex-col bg-slate-950 animate-in slide-in-from-bottom duration-300">
           <div className="p-4 pt-8 flex justify-between items-center bg-black/50 border-b border-white/5 shadow-2xl">
              <button onClick={() => setUiStep('crop')} className="flex items-center gap-2 text-slate-400 font-black text-[10px] uppercase tracking-widest px-4 py-2 rounded-xl bg-white/5">
                <i className="fas fa-arrow-left"></i> Crop
              </button>
              <h2 className="text-white font-black text-xs uppercase tracking-[0.4em]">Enhance</h2>
              <button onClick={acceptEnhancedPage} className="bg-teal-600 text-white px-8 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-2xl">
                Accept <i className="fas fa-check ml-1"></i>
              </button>
           </div>
           <div className="flex-1 p-8 flex items-center justify-center overflow-hidden">
              <img src={currentCapture} className={`max-w-full max-h-full object-contain transition-all duration-300 shadow-2xl rounded-xl border border-white/10 ${currentFilter === 'document' ? 'contrast-[1.25] grayscale brightness-110' : currentFilter === 'bw' ? 'grayscale contrast-[2.5]' : currentFilter === 'grayscale' ? 'grayscale' : ''}`} />
           </div>
           <div className="bg-black/90 p-6 flex gap-4 overflow-x-auto no-scrollbar border-t border-white/5 pb-14">
              {[
                { id: 'none', label: 'ORIGINAL', icon: 'fa-image' },
                { id: 'document', label: 'MAGIC B&W', icon: 'fa-wand-magic-sparkles' },
                { id: 'bw', label: 'SHARP B&W', icon: 'fa-circle-half-stroke' },
                { id: 'grayscale', label: 'GRAY', icon: 'fa-ghost' },
              ].map(f => (
                <button key={f.id} onClick={() => setCurrentFilter(f.id as any)} className={`flex flex-col items-center gap-3 p-5 min-w-[100px] rounded-3xl transition-all border-2 ${currentFilter === f.id ? 'bg-teal-600 border-teal-500 text-black shadow-2xl scale-105' : 'bg-white/5 border-white/5 text-slate-500'}`}>
                  <i className={`fas ${f.icon} text-xl`}></i>
                  <span className="text-[9px] font-black uppercase tracking-tighter">{f.label}</span>
                </button>
              ))}
           </div>
        </div>
      )}

      {/* Gallery / Finalize Step */}
      {uiStep === 'gallery' && (
        <div className="flex-1 flex flex-col bg-slate-50 dark:bg-slate-950 animate-in fade-in duration-300">
           <div className="p-4 pt-10 flex flex-col bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 shadow-sm">
              <div className="flex justify-between items-center mb-4 px-2">
                <button onClick={() => setUiStep('camera')} className="text-slate-500 text-xl active:scale-90 transition-transform"><i className="fas fa-arrow-left"></i></button>
                <div className="flex-1 px-4 text-center">
                   {isRenaming ? (
                     <input 
                       autoFocus 
                       value={fileName} 
                       onChange={e => setFileName(e.target.value)}
                       onBlur={() => setIsRenaming(false)}
                       onKeyDown={e => e.key === 'Enter' && setIsRenaming(false)}
                       className="w-full bg-slate-100 dark:bg-slate-800 p-2 rounded-xl font-black text-sm text-center outline-none border-2 border-teal-500 dark:text-white" 
                     />
                   ) : (
                     <h2 onClick={() => setIsRenaming(true)} className="text-slate-900 dark:text-white font-black text-sm uppercase truncate max-w-[200px] mx-auto flex items-center justify-center gap-2">
                       {fileName} <i className="fas fa-pen text-[10px] text-teal-500 opacity-40"></i>
                     </h2>
                   )}
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{capturedPages.length} Documents</p>
                </div>
                <div className="flex gap-4">
                   <button onClick={() => setIsSelectMode(!isSelectMode)} className={`text-xl transition-colors ${isSelectMode ? 'text-teal-500' : 'text-slate-400'}`}><i className="fas fa-check-double"></i></button>
                </div>
              </div>
           </div>

           <div className="flex-1 grid grid-cols-2 sm:grid-cols-3 gap-5 overflow-y-auto p-6 no-scrollbar">
              {capturedPages.map((p, i) => (
                <div key={p.id} onClick={() => isSelectMode && toggleSelect(p.id)} className={`relative aspect-[3/4] rounded-3xl overflow-hidden border-4 transition-all ${selectedIds.has(p.id) ? 'border-teal-500 scale-95 shadow-inner' : 'border-white dark:border-slate-800 bg-white dark:bg-slate-900 shadow-xl'}`}>
                   <img src={p.processed} className="w-full h-full object-cover" />
                   <div className="absolute top-4 left-4 bg-black/40 backdrop-blur-md text-white text-[9px] font-black px-2.5 py-1 rounded-lg">#{i+1}</div>
                   {isSelectMode && (
                     <div className={`absolute top-4 right-4 w-7 h-7 rounded-full flex items-center justify-center border-2 transition-all ${selectedIds.has(p.id) ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white/20 border-white text-transparent'}`}>
                       <i className="fas fa-check text-xs"></i>
                     </div>
                   )}
                   {!isSelectMode && (
                     <div className="absolute bottom-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={(e) => { e.stopPropagation(); setCapturedPages(prev => prev.filter(pg => pg.id !== p.id)) }} className="w-10 h-10 bg-rose-500 text-white rounded-xl flex items-center justify-center shadow-xl active:scale-90 transition-transform"><i className="fas fa-trash-alt text-sm"></i></button>
                     </div>
                   )}
                </div>
              ))}
           </div>

           <div className="bg-white dark:bg-slate-900 p-8 pb-14 border-t border-slate-100 dark:border-slate-800 flex gap-4 shadow-2xl">
              {isSelectMode ? (
                <>
                  <button onClick={deleteSelected} disabled={selectedIds.size === 0} className="flex-1 bg-rose-100 text-rose-600 py-5 rounded-3xl font-black text-xs uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-transform"><i className="fas fa-trash mr-2"></i> Delete ({selectedIds.size})</button>
                  <button onClick={() => { setIsSelectMode(false); setSelectedIds(new Set()); }} className="flex-1 bg-slate-100 dark:bg-slate-800 text-slate-500 py-5 rounded-3xl font-black text-xs uppercase tracking-widest active:scale-95 transition-transform">Cancel</button>
                </>
              ) : (
                <>
                  <button onClick={() => setUiStep('camera')} className="w-16 h-16 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-3xl flex items-center justify-center text-2xl active:scale-90 transition-transform"><i className="fas fa-plus"></i></button>
                  <button onClick={() => setShowShareModal(true)} className="flex-1 bg-teal-600 text-white py-5 rounded-3xl font-black text-lg shadow-2xl active:scale-95 transition-all">
                    SHARE OPTIONS
                  </button>
                </>
              )}
           </div>

           {/* Share Modal */}
           {showShareModal && (
             <div className="fixed inset-0 z-[10000] bg-black/60 backdrop-blur-md animate-in fade-in flex items-end">
                <div className="w-full bg-white dark:bg-slate-900 rounded-t-[3rem] p-10 pb-16 animate-in slide-in-from-bottom duration-500 max-w-xl mx-auto shadow-2xl">
                   <div className="flex justify-between items-center mb-10">
                      <h3 className="text-2xl font-black uppercase tracking-tighter">Share Options</h3>
                      <button onClick={() => setShowShareModal(false)} className="w-12 h-12 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-full flex items-center justify-center"><i className="fas fa-times"></i></button>
                   </div>
                   <div className="space-y-8">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Export Format</label>
                        <div className="flex bg-slate-100 dark:bg-slate-800/50 p-2 rounded-2xl">
                           <button onClick={() => setExportFormat('PDF')} className={`flex-1 py-4 rounded-xl font-black text-sm transition-all ${exportFormat === 'PDF' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-xl' : 'text-slate-500'}`}>PDF</button>
                           <button onClick={() => setExportFormat('JPG')} className={`flex-1 py-4 rounded-xl font-black text-sm transition-all ${exportFormat === 'JPG' ? 'bg-white dark:bg-slate-700 text-teal-600 shadow-xl' : 'text-slate-500'}`}>JPG</button>
                        </div>
                      </div>
                      <div className="flex gap-4">
                         <button onClick={() => setShowShareModal(false)} className="flex-1 bg-slate-100 dark:bg-slate-800 text-slate-500 py-6 rounded-3xl font-black text-sm uppercase active:scale-95 transition-transform">Cancel</button>
                         <button onClick={performExport} className="flex-1 bg-teal-600 text-white py-6 rounded-3xl font-black text-sm uppercase shadow-2xl active:scale-95 transition-transform">Process & Share</button>
                      </div>
                   </div>
                </div>
             </div>
           )}
        </div>
      )}

      {/* Idle / Landing Step */}
      {uiStep === 'idle' && state.status !== 'success' && (
        <div className="flex-1 flex flex-col items-center justify-center p-12 text-center bg-slate-950 h-full">
           <div className="w-28 h-28 bg-teal-500/10 text-teal-500 rounded-[2.5rem] flex items-center justify-center text-5xl mb-10 border border-teal-500/20 shadow-2xl">
             <i className="fas fa-camera"></i>
           </div>
           <h1 className="text-4xl font-black text-white mb-4 uppercase tracking-tighter">Pro Scanner</h1>
           <p className="text-slate-500 mb-12 font-medium text-sm max-w-xs mx-auto uppercase tracking-[0.3em]">Privacy-First • Local Export</p>
           <button 
            onClick={startCamera} 
            className="bg-teal-600 text-white px-14 py-6 rounded-3xl font-black text-xl shadow-2xl shadow-teal-600/20 active:scale-95 transition-all"
          >
            Start Scanning
          </button>
        </div>
      )}

      {/* Success View */}
      {state.status === 'success' && (
        <div className="fixed inset-0 z-[99999] bg-slate-950 flex flex-col items-center justify-center p-12 text-center animate-in zoom-in duration-500">
           <div className="w-28 h-28 bg-teal-500 text-white text-5xl rounded-[3rem] flex items-center justify-center mb-12 shadow-2xl border-4 border-white/10">
             <i className="fas fa-check-double"></i>
           </div>
           <h2 className="text-5xl font-black text-white mb-6 uppercase tracking-tighter">SUCCESS!</h2>
           <p className="text-slate-500 mb-14 font-black text-xs uppercase tracking-widest opacity-80">Output Ready for download</p>
           <div className="flex flex-col gap-5 w-full max-w-sm">
              <a href={state.resultUrl} download={state.resultFileName} className="bg-orange-500 text-white py-7 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-transform flex items-center justify-center gap-5">
                <i className="fas fa-file-download"></i> DOWNLOAD
              </a>
              <button 
                onClick={() => { setCapturedPages([]); setState({status:'idle', progress: 0}); setUiStep('idle'); }} 
                className="text-slate-500 font-black text-[11px] uppercase tracking-[0.4em] py-6 hover:text-teal-500 transition-colors"
              >
                START NEW SESSION
              </button>
           </div>
        </div>
      )}

      {/* Loading / Processing View */}
      {(state.status === 'processing' || state.status === 'loading') && (
        <div className="fixed inset-0 z-[30000] bg-black/95 backdrop-blur-3xl flex flex-col items-center justify-center p-12 text-center text-white">
           <div className="relative w-28 h-28 mb-12">
              <div className="absolute inset-0 border-[10px] border-white/5 rounded-full"></div>
              <div className="absolute inset-0 border-[10px] border-teal-500 border-t-transparent rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center text-teal-500 text-xl font-black">{state.progress}%</div>
           </div>
           <h2 className="text-3xl font-black mb-4 uppercase tracking-tighter">Working...</h2>
           <p className="text-white/40 font-black uppercase text-[10px] tracking-[0.6em]">{state.message || 'Optimizing Frames'}</p>
        </div>
      )}
    </div>
  );
};

