                  <div className={`w-6 h-6 bg-white rounded-full border-4 border-teal-500 shadow-xl ${draggingIdx === i ? 'scale-150 bg-teal-500' : ''}`}></div>
                </div>
              ))}
           </div>
           <div className="p-10 text-center bg-black/60 border-t border-white/5">
